/* content-04.js — notions n11 à n14 (diapos 21 à 28 du Chapitre 1). Schéma : voir content-core.js. */
(function (root) {
  'use strict';
  var GF = root.GF, GR = GF.graph, GS = GF.graphs, U = GF.u, X = GF.ex, qb = X.qb, mk = X.mk;
  function fr(a, b) { function g(x, y) { return y ? g(y, x % y) : x; } var d = g(a, b); a /= d; b /= d; return b === 1 ? String(a) : a + '/' + b; }
  function dec(x) { return X.fmtNum(Math.round(x * 1000) / 1000); }
  function Kn(s) { return mk(s, X.allPairs(s.split(''))); }
  function degList(G) { return G.vertices.map(function (v) { return 'd(' + v + ') = ' + GR.degree(G, v); }).join(', '); }
  function hasAll(g, vs) { return g.vertices.length === vs.length && vs.every(function (v) { return g.vertices.indexOf(v) >= 0; }); }
  var G10 = GS.get('s10'), G19 = GS.get('s19');

  /* ================= n11 ================= */
  (function () {
    function W(seq) { return { walk: { seq: seq, numbers: true } }; }
    var D11 = mk('123456', [['1', '2'], ['2', '3'], ['3', '1'], ['3', '4'], ['4', '5'], ['5', '4'], ['5', '6']], { directed: true });
    var CYC4 = mk('1234', [['1', '2'], ['2', '3'], ['3', '4'], ['4', '1']], { directed: true });
    var TRI = mk('ABC', ['AB', 'BC', 'CA']);
  GF.content.add({
    id: 'n11', title: 'Composantes connexes et fortement connexes', short: 'Composantes CC et CFC', slides: '21', prereqs: ['n09', 'n08'],
    objectives: [
      'Déterminer la composante connexe CC(s) d’un sommet dans un graphe non orienté (sommets accessibles depuis s, s compris).',
      'Compter les composantes connexes d’un graphe et savoir qu’un sommet isolé forme à lui seul une composante.',
      'Déterminer la composante fortement connexe CFC(s) dans un graphe orienté (sommets mutuellement accessibles).',
      'Distinguer « accessible depuis s » (un seul sens) de « mutuellement accessible » (les deux sens).'
    ],
    course: [
      { k: 'def', slide: '21', t: 'Composante connexe CC(s)', h: '<p>La <b>composante connexe</b> d’un sommet <i>s</i>, notée <b>CC(s)</b>, est l’<b>ensemble des sommets accessibles depuis s</b>, y compris <i>s</i>, dans un graphe <b>non orienté</b>.</p><p>Sur le graphe de la diapo 19 : CC(1) = {1, 2, 3, 4} et CC(5) = CC(6) = {5, 6}.</p>', g: 's19', go: { hlV: { '1': 'hl', '2': 'hl', '3': 'hl', '4': 'hl' } } },
      { k: 'def', slide: '21', t: 'Composante fortement connexe CFC(s)', h: '<p>La <b>composante fortement connexe</b> d’un sommet <i>s</i> d’un graphe <b>orienté</b>, notée <b>CFC(s)</b>, est l’<b>ensemble maximal de sommets mutuellement accessibles</b> dans un graphe orienté.</p>' },
      { k: 'warn', slide: '21', t: 'Connexité forte : aucune définition de la propriété', h: '<p>Le cours définit CC(s) et CFC(s) mais pas « graphe fortement connexe ». <b>Hors cours :</b> on dit qu’un graphe orienté est fortement connexe s’il n’a qu’<b>une seule</b> CFC (comme le graphe non orienté est connexe quand il n’a qu’une seule composante). La diapo 19 définit la connexité par « toute paire est reliée » ; la diapo 21 ne reprend pas cette formulation pour le cas orienté.</p>' },
      { k: 'warn', slide: '21', t: 'La figure de la diapo 21', h: '<p>La figure de la diapo 21 montre un graphe orienté dont les composantes fortement connexes sont entourées par des zones colorées. Ses arcs ne sont pas listés ; l’application ne la reproduit pas et utilise à la place des exemples construits à la main (signalés « hors diapo »).</p>' },
      { k: 'warn', slide: '21', t: '« Mutuellement accessibles » non précisé', h: '<p>Le mot « accessible » n’est pas défini explicitement dans le cours : on le lit comme « il existe une chaîne (graphe non orienté) ou un chemin (graphe orienté, diapo 18) de s vers t ». « Mutuellement accessibles » veut dire : un chemin de s à t <b>et</b> un chemin de t à s.</p>' },
      { k: 'extra', t: 'Exemple orienté : trois CFC (hors diapo)', h: '<p>Dans ce graphe orienté (arcs 1→2, 2→3, 3→1, 3→4, 4→5, 5→4, 5→6), les composantes fortement connexes sont <b>{1, 2, 3}</b> (le circuit 1→2→3→1), <b>{4, 5}</b> (4→5 et 5→4) et <b>{6}</b>. Depuis 1 on peut atteindre tous les sommets, mais CFC(1) = {1, 2, 3} : on ne peut pas revenir en 1 depuis 4, 5 ou 6.</p>', g: D11, go: { hlV: { '1': 'hl', '2': 'hl', '3': 'hl' } } },
      { k: 'extra', t: 'Les composantes forment une partition (hors diapo)', h: '<p>Chaque sommet appartient à exactement une composante connexe (et à exactement une CFC dans un graphe orienté) : CC(s) = CC(t) dès que t est dans CC(s). Un graphe est connexe exactement quand il n’a qu’une seule composante ; un graphe orienté est fortement connexe quand il n’a qu’une seule CFC (comme le circuit 1→2→3→4→1).</p>', g: CYC4 },
      { k: 'extra', t: 'Ignorer le sens des arcs (hors diapo)', h: '<p>Le graphe orienté de l’exemple ci-dessus, vu sans le sens de ses arcs, est connexe (une seule composante connexe), mais il n’est <b>pas</b> fortement connexe : il a trois CFC. Un graphe orienté peut donc être « d’un seul tenant » sans que l’on puisse revenir en arrière.</p>', g: D11 }
    ],
    guided: [
      { h: '<p>La composante connexe d’un sommet est l’ensemble des sommets qu’on peut atteindre en suivant des arêtes, en comptant le sommet lui-même.</p>', g: 's19', ask: 'Quelle est la composante connexe CC(1) du graphe de la diapo 19 ?', reveal: '<p>Depuis 1 on atteint 3 et 4, puis 2 (par 3) : CC(1) = {1, 2, 3, 4}. On n’atteint jamais 5 ni 6.</p>' },
      { h: '<p>Il reste les sommets 5 et 6, reliés entre eux seulement.</p>', g: 's19', go: { hlV: { '5': 'hl', '6': 'hl' } }, ask: 'Quelle est CC(5) ? Combien le graphe a-t-il de composantes connexes ?', reveal: '<p>CC(5) = {5, 6}. Il y a deux composantes : {1, 2, 3, 4} et {5, 6}. Le graphe n’est pas connexe (diapo 19).</p>' },
      { h: '<p>Dans un graphe orienté, il faut respecter le sens des arcs. Arcs : 1→2, 2→3, 3→1, 3→4, 4→5, 5→4, 5→6.</p>', g: D11, ask: '4 est accessible depuis 1. 1 est-il accessible depuis 4 ? 1 et 4 sont-ils dans la même CFC ?', reveal: '<p>Non : depuis 4 on atteint 5 et 6 (et 4), jamais 1. Il n’y a pas de chemin de 4 vers 1, donc 1 et 4 ne sont pas mutuellement accessibles : ils ne sont pas dans la même CFC.</p>' },
      { h: '<p>Cherchons maintenant les sommets mutuellement accessibles avec 4.</p>', g: D11, go: { hlV: { '4': 'hl', '5': 'hl' } }, ask: 'Quelle est CFC(4) ?', reveal: '<p>4→5 et 5→4 : 4 et 5 sont mutuellement accessibles. 6 est accessible depuis 4 mais on ne peut pas en revenir. CFC(4) = {4, 5}.</p>' },
      { h: '<p>Récapitulons toutes les CFC du graphe orienté.</p>', g: D11, ask: 'Combien de composantes fortement connexes ce graphe a-t-il ?', reveal: '<p>Trois : {1, 2, 3}, {4, 5} et {6} (un sommet seul est toujours mutuellement accessible avec lui-même).</p>' }
    ],
    examples: [
      { t: 'Composantes connexes du graphe de la diapo 19', h: '<p>Deux composantes : {1, 2, 3, 4} et {5, 6}. CC(2) = CC(1).</p>', g: 's19', go: { hlV: { '5': 'hl', '6': 'hl' } } },
      { t: 'Un triangle : une seule composante', h: '<p>Dans le triangle A–B–C, CC(A) = {A, B, C} : le graphe est connexe.</p>', g: TRI },
      { t: 'Un circuit orienté : une seule CFC', h: '<p>Dans 1→2→3→4→1, chaque sommet atteint tous les autres et inversement : une seule CFC, {1, 2, 3, 4}.</p>', g: CYC4 },
      { t: 'Trois CFC dans un même graphe orienté', h: '<p>{1, 2, 3}, {4, 5} et {6}.</p>', g: D11, go: { hlV: { '4': 'hl', '5': 'hl' } } },
      { t: 'Contre-exemple : accessible n’est pas mutuellement accessible', h: '<p>Dans le graphe orienté, 6 est accessible depuis 1 (1→2→3→4→5→6) mais 1 n’est pas accessible depuis 6 : 1 et 6 ne sont pas dans la même CFC.</p>', g: D11, go: { hlV: { '1': 'hl', '6': 'hl' } }, counter: true },
      { t: 'Contre-exemple : un sommet isolé est une composante', h: '<p>Un sommet sans arête, comme 5 dans un graphe où il n’est relié à personne, forme sa propre composante : CC(5) = {5} (le sommet s lui-même est toujours dans CC(s)).</p>', g: mk('ABCDE', ['AB', 'BC', 'CA', 'DE']), go: { hlV: { D: 'hl', E: 'hl' } }, counter: true }
    ],
    compare: [{ t: 'CC(s) et CFC(s)', cols: ['', 'CC(s)', 'CFC(s)'], rows: [['Type de graphe', 'non orienté', 'orienté'], ['Définition', 'sommets accessibles depuis s, s compris', 'ensemble maximal de sommets mutuellement accessibles'], ['Sens de parcours', 'sans importance', 'les arcs doivent être respectés, dans les deux directions'], ['Exemple', 'CC(1) = {1, 2, 3, 4} (diapo 19)', 'CFC(4) = {4, 5} (graphe orienté ci-dessus)']] }],
    mistakes: [
      { tag: 'composantes', wrong: 'CC(s) est l’ensemble des voisins de s.', right: 'CC(s) contient <b>tous</b> les sommets accessibles depuis s (par des chaînes de n’importe quelle longueur), s lui-même compris : CC(1) = {1, 2, 3, 4} sur la diapo 19, alors que 1 n’a que 3 et 4 pour voisins.' },
      { tag: 'composantes-orientees', wrong: 'Dans un graphe orienté, si t est accessible depuis s, alors t est dans CFC(s).', right: 'Il faut aussi que s soit accessible depuis t (<b>mutuellement</b> accessibles). Exemple : 6 est accessible depuis 1 mais 1 ne l’est pas depuis 6.' },
      { tag: 'composantes', wrong: 'Un sommet isolé n’appartient à aucune composante.', right: 'Il forme sa propre composante : CC(s) = {s} (« y compris s », diapo 21).' },
      { tag: 'composantes-orientees', wrong: 'Si le graphe est connexe quand on ignore le sens des arcs, il est fortement connexe.', right: 'Non : le graphe orienté de l’exemple est d’un seul tenant mais a trois CFC.' },
      { tag: 'composantes', wrong: 'Le nombre de composantes connexes est le nombre de sommets de degré 0.', right: 'Les composantes peuvent contenir beaucoup de sommets : le graphe de la diapo 19 n’a aucun sommet isolé mais deux composantes.' }
    ],
    alt: [
      '<p>Imaginez une carte routière : <b>CC(s)</b> est l’ensemble des villes où l’on peut aller en partant de s (on peut toujours revenir sur ses pas, les routes sont à double sens). Pour <b>CFC(s)</b>, les routes sont à <b>sens unique</b> : il faut qu’on puisse aller <i>et</i> revenir.</p>',
      '<p>Pour trouver CC(s) : colorez s, puis colorez les voisins des sommets colorés, jusqu’à ce que plus rien ne change. Pour CFC(s) : colorez les sommets accessibles depuis s <i>et</i> ceux qui peuvent atteindre s ; gardez ceux qui sont dans les deux ensembles.</p>',
      '<p>Un graphe orienté est « d’un seul morceau fort » s’il existe un grand circuit qui passe par tous les sommets, ou de tels circuits qui s’enchaînent.</p>'
    ],
    socratic: {
      warm: { id: 'n11.s0', type: 'choice', q: 'Dans un graphe non orienté, que veut dire « t est accessible depuis s » ?', options: ['Il existe une chaîne de s à t', 'Il existe une arête entre s et t', 'd(s) = d(t)', 'δ(s, t) = 1'], answer: 0,
        counter: '<p>Cas plus simple : dans un chemin A–B–C, C est-il accessible depuis A ? Y a-t-il une arête entre A et C ?</p>', hints: ['<p>« Accessible » autorise de passer par plusieurs arêtes (voir la diapo 18 sur les chaînes).</p>', '<p>Adjacent = une arête ; accessible = une chaîne, de n’importe quelle longueur.</p>'],
        ok: '<p>Exact. L’ensemble de tous les sommets accessibles depuis s a un nom dans le cours : lequel ?</p>', explain: '<p>« Accessible » signifie qu’il existe une chaîne (de n’importe quelle longueur) de s à t. Exemple : dans A–B–C, C est accessible depuis A (chaîne A–B–C) bien qu’il n’y ait pas d’arête {A, C}.</p>', restate: '<p>Redites avec vos mots la différence entre adjacent et accessible.</p>' },
      steps: [
        { id: 'n11.s1', type: 'set', g: 's19', q: 'Donnez la composante connexe <b>CC(1)</b> du graphe de la diapo 19 (ensemble des sommets accessibles depuis 1, y compris 1).', answer: function (G) { return GR.componentOf(G, '1'); },
          counter: '<p>Cas plus simple : dans un triangle A–B–C, quelle est CC(A) ?</p>', hints: ['<p>Partez de 1 et ajoutez ses voisins, puis les voisins de ces voisins.</p>', '<p>N’oubliez pas le sommet 2, atteint par 3.</p>'],
          ok: '<p>Oui : {1, 2, 3, 4}. Que dire des sommets 5 et 6 ?</p>', explain: '<p>Depuis 1 on atteint 3 et 4, puis 2 par 3 : CC(1) = {1, 2, 3, 4}. Exemple : dans un triangle, CC(A) = {A, B, C}.</p>', restate: '<p>Redites ce qu’est une composante connexe.</p>' },
        { id: 'n11.s2', type: 'num', g: 's19', q: 'Combien le graphe de la diapo 19 a-t-il de <b>composantes connexes</b> ?', answer: function (G) { return GR.components(G).length; },
          counter: '<p>Cas plus simple : deux triangles disjoints ont combien de composantes ?</p>', hints: ['<p>Calculez CC(1), puis CC d’un sommet non atteint.</p>', '<p>Chaque sommet est dans exactement une composante.</p>'],
          ok: '<p>Oui, 2. Ce graphe est-il connexe ?</p>', explain: '<p>Les composantes sont {1, 2, 3, 4} et {5, 6} : deux. Un graphe est connexe quand il n’en a qu’une seule. Exemple : deux triangles disjoints ont 2 composantes.</p>', restate: '<p>Reformulez le lien entre composantes et connexité.</p>' },
        { id: 'n11.s3', type: 'choice', g: D11, q: 'Dans ce graphe orienté (arcs 1→2, 2→3, 3→1, 3→4, 4→5, 5→4, 5→6), 6 est accessible depuis 1. Les sommets 1 et 6 sont-ils dans la même CFC ?', options: ['Oui : 6 est accessible depuis 1', 'Non : 1 n’est pas accessible depuis 6', 'Oui : le graphe est connexe', 'Non : 6 n’a pas de voisin'], answer: 1,
          counter: '<p>Cas plus simple : avec le seul arc 1→2, 1 et 2 sont-ils mutuellement accessibles ?</p>', hints: ['<p>Y a-t-il un chemin de 6 vers 1 ?</p>', '<p>CFC = mutuellement accessibles : il faut les deux sens (diapo 21).</p>'],
          ok: '<p>Bien vu. Quelle est alors CFC(6) ?</p>', explain: '<p>Aucun arc ne part de 6 : il n’y a pas de chemin de 6 vers 1, donc 1 et 6 ne sont pas mutuellement accessibles. Exemple : avec le seul arc 1→2, 2 est accessible depuis 1 mais pas l’inverse.</p>', restate: '<p>Redites la différence entre « accessible » et « mutuellement accessible ».</p>' },
        { id: 'n11.s4', type: 'set', g: D11, q: 'Donnez la composante fortement connexe <b>CFC(4)</b> de ce graphe orienté.', answer: function (G) { return GR.sccOf(G, '4'); },
          counter: '<p>Cas plus simple : avec les arcs 1→2 et 2→1, quelle est CFC(1) ?</p>', hints: ['<p>Cherchez les sommets u tels qu’il existe un chemin de 4 à u <i>et</i> un chemin de u à 4.</p>', '<p>6 est atteint depuis 4 : peut-on revenir de 6 à 4 ?</p>'],
          ok: '<p>Oui : {4, 5}. Combien le graphe a-t-il de CFC au total ?</p>', explain: '<p>4→5 et 5→4 : 4 et 5 sont mutuellement accessibles. 6 est accessible depuis 4 mais n’a aucun arc sortant ; 1, 2, 3 ne sont pas accessibles depuis 4. CFC(4) = {4, 5}. Exemple : avec les arcs 1→2 et 2→1, CFC(1) = {1, 2}.</p>', restate: '<p>Redites la méthode : quels sommets garde-t-on dans CFC(s) ?</p>' },
        { id: 'n11.s5', type: 'text', q: 'Expliquez avec vos mots la différence entre la composante connexe CC(s) et la composante fortement connexe CFC(s), avec un exemple.', expect: ['CC(s) : sommets accessibles depuis s dans un graphe non orienté (s compris)', 'CFC(s) : ensemble maximal de sommets mutuellement accessibles dans un graphe orienté', 'Dans l’orienté il faut un chemin dans les deux sens ; exemple : 6 est accessible depuis 1 mais pas dans CFC(1)'],
          counter: '<p>Dans un graphe orienté avec le seul arc 1→2, quels sommets sont accessibles depuis 1 ? Lesquels sont mutuellement accessibles avec 1 ?</p>', hints: ['<p>Pensez au sens des arcs : un sens ou les deux ?</p>', '<p>Utilisez l’exemple à trois CFC.</p>'],
          ok: '<p>Bien. Un graphe orienté peut-il avoir une seule composante connexe (en ignorant les arcs) et plusieurs CFC ?</p>', explain: '<p>CC(s) concerne un graphe non orienté : tout sommet qu’on peut atteindre par une chaîne. CFC(s) concerne un graphe orienté : il faut atteindre t depuis s <i>et</i> s depuis t. Exemple : dans l’exemple, 6 est accessible depuis 1 mais 1 ne l’est pas depuis 6, donc 6 n’est pas dans CFC(1) = {1, 2, 3}.</p>', restate: '<p>Reformulez en une phrase ce que « mutuellement » apporte à la définition.</p>' }
      ],
      verify: { gen: 'comp', level: 2 }
    },
    feynman: {
      topic: 'Composantes connexes et fortement connexes',
      prompt: 'Expliquez à un débutant ce que sont la composante connexe CC(s) et la composante fortement connexe CFC(s), avec un exemple et un contre-exemple.',
      must: ['CC(s) : sommets accessibles depuis s, s compris, dans un graphe non orienté (diapo 21)', 'CFC(s) : ensemble maximal de sommets mutuellement accessibles dans un graphe orienté', '« Mutuellement » : un chemin dans chaque sens', 'Un exemple (diapo 19 : CC(1) = {1, 2, 3, 4}) et un contre-exemple (accessible mais pas mutuellement accessible)', 'Un graphe est connexe quand il n’a qu’une composante'],
      pitfalls: ['Confondre CC(s) avec les voisins de s', 'Oublier que, dans un graphe orienté, il faut aller ET revenir', 'Oublier que s appartient à CC(s)'],
      beginner: ['Quelle est la composante d’un sommet isolé ?', 'Pourquoi dans un graphe orienté ne suffit-il pas d’atteindre un sommet ?', 'Combien de composantes un graphe connexe a-t-il ?', 'Peut-on être dans la CFC de s sans être voisin de s ?'],
      model: '<p>Dans un graphe <b>non orienté</b>, la <b>composante connexe</b> CC(s) est l’ensemble des sommets qu’on peut atteindre depuis s en suivant des arêtes (s compris). Sur la diapo 19, CC(1) = {1, 2, 3, 4} et CC(5) = {5, 6} : deux composantes, le graphe n’est pas connexe. Dans un graphe <b>orienté</b>, la <b>composante fortement connexe</b> CFC(s) est le plus grand ensemble de sommets <b>mutuellement accessibles</b> : on peut aller de l’un à l’autre <i>et</i> revenir en suivant le sens des arcs. Contre-exemple : 6 est accessible depuis 1 mais 1 n’est pas accessible depuis 6, donc 6 n’est pas dans CFC(1).</p>'
    },
    recap: {
      key: ['CC(s) : ensemble des sommets accessibles depuis s, y compris s, dans un graphe non orienté (diapo 21).', 'CFC(s) : ensemble maximal de sommets mutuellement accessibles dans un graphe orienté (diapo 21).', 'Mutuellement accessible = un chemin dans chaque sens.', 'Hors cours : les composantes partitionnent les sommets ; graphe connexe = une seule composante ; graphe fortement connexe = une seule CFC.'],
      defs: [{ t: 'Composante connexe CC(s)', d: 'Ensemble des sommets accessibles depuis s, y compris s, dans un graphe non orienté.', slide: '21' }, { t: 'Composante fortement connexe CFC(s)', d: 'Ensemble maximal de sommets mutuellement accessibles dans un graphe orienté.', slide: '21' }],
      thms: [],
      formulas: []
    },
    qs: [
      qb.choice('n11.q1', 1, 'D’après la diapo 21, la composante connexe CC(s) d’un sommet s est…', ['l’ensemble des sommets accessibles depuis s, y compris s', 'l’ensemble des voisins de s', 'le nombre de sommets du graphe', 'l’ensemble des sommets de même degré que s'], 0, '<p>CC(s) est l’ensemble des sommets accessibles depuis s, y compris s, dans un graphe non orienté (diapo 21).</p>', { src: 'course', slide: '21', tag: 'composantes', hints: ['Relisez la première puce de la diapo 21.'] }),
      qb.set('n11.q2', 1, 'Donnez la composante connexe CC(6) du graphe de la diapo 19.', ['5', '6'], '<p>6 n’est relié qu’à 5 : CC(6) = {5, 6}.</p>', { graph: 's19', src: 'course', slide: '21', tag: 'composantes', hints: ['Quels sommets peut-on atteindre depuis 6 ?'] }),
      qb.text('n11.q3', 1, 'Expliquez avec vos mots ce qu’est une composante fortement connexe et en quoi elle diffère d’une composante connexe.', '<p>Une composante fortement connexe CFC(s) est l’ensemble maximal de sommets mutuellement accessibles dans un graphe orienté : pour deux sommets u et v de CFC(s), il existe un chemin de u à v <i>et</i> un chemin de v à u. La composante connexe CC(s), elle, concerne un graphe non orienté : tous les sommets accessibles depuis s.</p>', ['CFC(s) : ensemble maximal de sommets mutuellement accessibles', 'Graphe orienté : il faut respecter le sens des arcs', 'Mutuellement : un chemin dans chaque sens', 'CC(s) : graphe non orienté, sommets accessibles depuis s'], { src: 'course', slide: '21', tag: 'composantes-orientees', hints: ['Reprenez la deuxième puce de la diapo 21.'] }),
      qb.num('n11.q4', 2, 'Combien de composantes connexes ce graphe a-t-il ?', function (G) { return GR.components(G).length; }, function (G) { return '<p>Composantes : ' + GR.components(G).map(U.set).join(' ; ') + '. Il y en a ' + GR.components(G).length + '.</p>'; }, { graph: 's19', tag: 'composantes', hints: ['Partez d’un sommet, puis d’un sommet non atteint.'] }),
      qb.tf('n11.q5', 2, 'Dans ce graphe orienté, 6 est accessible depuis 1 ; les sommets 1 et 6 appartiennent donc à la même composante fortement connexe.', false, ['Il faudrait aussi que 1 soit accessible depuis 6 ; or aucun arc ne part de 6.', 'Parce que 6 est de degré 1.', 'Parce que le graphe n’est pas complet.', 'Parce que 1 et 6 ne sont pas adjacents.'], 0, '<p>Pour être dans la même CFC, deux sommets doivent être <b>mutuellement</b> accessibles. 6 est accessible depuis 1, mais aucun arc ne part de 6 : on ne peut pas revenir. CFC(1) = {1, 2, 3} et CFC(6) = {6}.</p>', { graph: D11, tag: 'composantes-orientees', hints: ['Y a-t-il un chemin de 6 vers 1 ?'] }),
      qb.set('n11.q6', 2, 'Donnez la composante fortement connexe CFC(1) de ce graphe orienté.', function (G) { return GR.sccOf(G, '1'); }, function (G) { return '<p>1→2→3→1 est un circuit : 1, 2, 3 sont mutuellement accessibles. 4, 5, 6 sont accessibles depuis 1 mais on ne peut pas en revenir. CFC(1) = ' + U.set(GR.sccOf(G, '1')) + '.</p>'; }, { graph: D11, tag: 'composantes-orientees', hints: ['Cherchez un circuit passant par 1.'] }),
      qb.num('n11.q7', 2, 'Combien de composantes fortement connexes ce graphe orienté a-t-il ?', function (G) { return GR.scc(G).length; }, function (G) { return '<p>Composantes fortement connexes : ' + GR.scc(G).map(U.set).join(' ; ') + '. Il y en a ' + GR.scc(G).length + ' (un sommet seul forme une CFC).</p>'; }, { graph: D11, tag: 'composantes-orientees', hints: ['Cherchez d’abord les circuits, puis comptez les sommets restants.'] }),
      qb.choice('n11.q8', 3, 'Combien de composantes fortement connexes comporte ce circuit orienté 1→2→3→4→1 ?', ['1', '2', '4', '0'], 0, '<p>Chaque sommet atteint tous les autres en suivant les arcs, et inversement : les quatre sommets sont mutuellement accessibles. Il y a une seule CFC, {1, 2, 3, 4} : le graphe est fortement connexe (au sens hors cours).</p>', { graph: CYC4, tag: 'composantes-orientees', hints: ['Peut-on aller de 2 à 1 en suivant les arcs ?'] }),
      qb.choice('n11.q9', 3, 'Dans un site web (pages = sommets, lien hypertexte de A vers B = arc A→B), deux pages sont dans la même composante fortement connexe quand…', ['on peut aller de l’une à l’autre, et inversement, en suivant des liens', 'elles se citent directement l’une l’autre', 'on peut aller de la première à la seconde en suivant des liens', 'elles ont le même nombre de liens'], 0, '<p>CFC = sommets mutuellement accessibles : un chemin de A à B <i>et</i> un chemin de B à A, pas nécessairement des liens directs. Pouvoir aller de A à B seulement (un sens) ne suffit pas.</p>', { transfer: true, tag: 'composantes-orientees', hints: ['Modélisez : pages = sommets, liens = arcs.', 'Il faut les deux sens.'] }),
      qb.edges('n11.q10', 3, 'Écrivez la liste des arêtes d’un graphe simple non orienté sur les six sommets A, B, C, D, E, F qui a <b>exactement 3 composantes connexes</b>, dont l’une est un triangle. (Un sommet sans arête s’écrit seul, par exemple « F ».)', function (g) {
        var vs = ['A', 'B', 'C', 'D', 'E', 'F'];
        if (!hasAll(g, vs)) return { ok: false, msg: 'Le graphe doit avoir exactement les six sommets A à F.' };
        if (!GR.isSimple(g)) return { ok: false, msg: 'Le graphe doit être simple (ni boucle, ni arête répétée).' };
        var cs = GR.components(g);
        if (cs.length !== 3) return { ok: false, msg: 'Votre graphe a ' + cs.length + ' composante(s) : ' + cs.map(U.set).join(' ; ') + '. Il en faut 3.' };
        var tri = cs.some(function (c) { return c.length === 3 && GR.isClique(g, c); });
        if (!tri) return { ok: false, msg: 'Aucune composante n’est un triangle (3 sommets deux à deux adjacents).' };
        return { ok: true };
      }, '<p>Triangle A–B–C, arête D–E, et sommet F isolé : trois composantes {A, B, C}, {D, E}, {F}.</p>', { sample: 'A-B, B-C, C-A, D-E, F', challenge: true, tag: 'composantes', hints: ['Le triangle utilise 3 sommets ; il en reste 3 à répartir en 2 composantes.', 'Un sommet isolé est une composante à lui seul.'] })
    ]
  });
  })();
  /* ================= n12 ================= */
  (function () {
    var G22 = GS.get('s22');
    var NEITHER = mk('12356', ['13', '56']);
    var HV = mk('123456', ['13', '14', '23', '34', '56']);
    function inducedCount(G, A) { return GR.inducedSubgraph(G, A).edges.length; }
  GF.content.add({
    id: 'n12', title: 'Graphe partiel et sous-graphe', short: 'Graphe partiel, sous-graphe', slides: '22', prereqs: ['n01', 'n10'],
    objectives: [
      'Obtenir un graphe partiel de G : on garde tous les sommets et on enlève une ou plusieurs arêtes.',
      'Obtenir le sous-graphe de G sur A ⊆ V : on garde les sommets de A et toutes les arêtes de G entre sommets de A.',
      'Décider si un graphe H donné est un graphe partiel, un sous-graphe, les deux ou aucun des deux.',
      'Lister les arêtes du sous-graphe de G induit par un ensemble de sommets A donné.'
    ],
    course: [
      { k: 'def', slide: '22', t: 'Graphe partiel', h: '<p>Un graphe <i>G′ = (V, E′)</i> est un <b>graphe partiel</b> de <i>G(V, E)</i> si on obtient <i>G′</i> en <b>enlevant une ou plusieurs arêtes</b> au graphe <i>G</i>.</p><p>Exemple de la diapo 22 : G a les arêtes {1,3}, {1,4}, {2,3}, {3,4}, {4,5}, {5,6} ; le graphe partiel ci-contre garde les six sommets mais seulement {1,3}, {1,4}, {2,3}, {5,6} (on a retiré {3,4} et {4,5}).</p>', g: 's22p' },
      { k: 'def', slide: '22', t: 'Sous-graphe', h: '<p>Un graphe <i>G′ = (A, E(A))</i> est un <b>sous-graphe</b> de <i>G</i>, si <i>A</i> est un <b>sous-ensemble de sommets</b> de <i>V</i> et <i>E(A)</i> est formé de <b>toutes les arêtes de G ayant leurs deux extrémités dans A</b>.</p><p>Exemple de la diapo 22 : avec A = {1, 2, 3, 5, 6}, le sous-graphe a pour arêtes {1,3}, {2,3}, {5,6} : le sommet 4 est supprimé avec toutes ses arêtes ({1,4}, {3,4}, {4,5}).</p>', g: 's22s' },
      { k: 'def', slide: '22', t: 'Le graphe G de la diapo 22', h: '<p>V = {1, 2, 3, 4, 5, 6} et E = {{1,3}, {1,4}, {2,3}, {3,4}, {4,5}, {5,6}}.</p>', g: 's22' },
      { k: 'warn', slide: '22', t: '« Sous-graphe » = sous-graphe induit', h: '<p>Dans ce cours, un sous-graphe (A, E(A)) contient <b>toutes</b> les arêtes de G entre sommets de A (ce que d’autres sources appellent un sous-graphe <i>induit</i>). Un graphe partiel garde tous les sommets mais retire des arêtes. Le PDF ne définit pas de notion combinant les deux (supprimer des sommets <i>et</i> des arêtes en plus).</p>' },
      { k: 'warn', slide: '22', t: '« Une ou plusieurs arêtes »', h: '<p>La définition du graphe partiel dit « en enlevant une ou plusieurs arêtes » : lue à la lettre, G lui-même (zéro arête enlevée) n’est pas un graphe partiel de G. L’application accepte un graphe qui garde tous les sommets de G et dont les arêtes sont parmi celles de G, G lui-même compris ; dans les exercices, les graphes partiels générés ont au moins une arête retirée.</p>' },
      { k: 'extra', t: 'Deux tests rapides (hors diapo)', h: '<p><b>Graphe partiel ?</b> H a-t-il exactement les mêmes sommets que G, et toutes ses arêtes sont-elles des arêtes de G ? <b>Sous-graphe ?</b> Les sommets de H sont-ils parmi ceux de G, et H contient-il <i>toutes</i> les arêtes de G entre ses sommets ?</p>', g: 's22' },
      { k: 'extra', t: 'Quatre cas (hors diapo)', h: '<p>Un graphe H construit à partir de G peut être : un graphe partiel seulement (les six sommets, des arêtes en moins) ; un sous-graphe seulement (certains sommets, toutes les arêtes entre eux) ; <b>les deux</b> (si A = V et toutes les arêtes sont gardées : H = G) ; <b>aucun des deux</b> (on supprime un sommet et, en plus, une arête qu’on aurait dû garder).</p>', g: NEITHER },
      { k: 'extra', t: 'Lien avec les cliques (hors diapo)', h: '<p>Une clique (diapo 20) est un sous-graphe complet : on choisit un ensemble A de sommets deux à deux adjacents, et le sous-graphe sur A est complet. Dans G (diapo 22), le sous-graphe sur A = {1, 3, 4} a les arêtes {1,3}, {1,4}, {3,4} : c’est un triangle, donc une clique.</p>', g: 's22', go: { hlV: { '1': 'hl', '3': 'hl', '4': 'hl' } } }
    ],
    guided: [
      { h: '<p>Voici le graphe partiel de la diapo 22. Comparez avec G (arêtes {1,3}, {1,4}, {2,3}, {3,4}, {4,5}, {5,6}).</p>', g: 's22p', ask: 'Quelles arêtes a-t-on retirées à G ? A-t-on retiré des sommets ?', reveal: '<p>On a retiré {3,4} et {4,5}. Aucun sommet n’est retiré : les six sommets sont conservés (le sommet 4 reste, avec les arêtes {1,4} seulement). C’est un <b>graphe partiel</b>.</p>' },
      { h: '<p>Voici maintenant le sous-graphe de la diapo 22, sur A = {1, 2, 3, 5, 6}.</p>', g: 's22s', ask: 'Quel sommet a été retiré ? Quelles arêtes disparaissent avec lui ?', reveal: '<p>Le sommet 4 est retiré, donc toutes les arêtes qui le touchent disparaissent : {1,4}, {3,4}, {4,5}. Les arêtes {1,3}, {2,3}, {5,6} ont leurs deux extrémités dans A : elles restent. C’est un <b>sous-graphe</b>.</p>' },
      { h: '<p>Testons un graphe H = (V, {1,3}, {1,4}, {2,3}, {3,4}, {5,6}) : tous les sommets de G, et on a seulement retiré {4,5}.</p>', g: HV, ask: 'H est-il un graphe partiel de G ? Est-il un sous-graphe de G ?', reveal: '<p>Graphe partiel : oui, les six sommets sont gardés et on a seulement retiré {4,5}. Sous-graphe : non. Avec A = V, il faudrait garder <b>toutes</b> les arêtes de G, y compris {4,5}.</p>' },
      { h: '<p>Un dernier cas : H a les sommets 1, 2, 3, 5, 6 et les arêtes {1,3}, {5,6} seulement.</p>', g: NEITHER, ask: 'H est-il un graphe partiel de G ? un sous-graphe de G ?', reveal: '<p>Ni l’un ni l’autre. Pas un graphe partiel : le sommet 4 manque. Pas un sous-graphe : il manque l’arête {2,3}, dont les deux extrémités sont dans A = {1, 2, 3, 5, 6}.</p>' },
      { h: '<p>Pour construire un sous-graphe, on choisit A puis on garde toutes les arêtes de G dans A.</p>', g: 's22', go: { hlV: { '3': 'hl', '4': 'hl', '5': 'hl' } }, ask: 'Combien d’arêtes a le sous-graphe de G sur A = {3, 4, 5} ?', reveal: '<p>Les arêtes de G entre sommets de A sont {3,4} et {4,5}. {1,3}, {2,3}, {1,4}, {5,6} ont une extrémité hors de A. Le sous-graphe a donc 2 arêtes.</p>' }
    ],
    examples: [
      { t: 'Un graphe partiel de G : on retire {3,4} et {4,5}', h: '<p>Les six sommets sont gardés ; les arêtes restantes {1,3}, {1,4}, {2,3}, {5,6} sont des arêtes de G.</p>', g: 's22p' },
      { t: 'Un sous-graphe de G : A = {1, 2, 3, 5, 6}', h: '<p>On supprime le sommet 4 et ses trois arêtes ; on garde {1,3}, {2,3}, {5,6}.</p>', g: 's22s' },
      { t: 'Un graphe à la fois partiel et sous-graphe : G lui-même', h: '<p>En gardant tous les sommets et toutes les arêtes, on retrouve G. (Voir l’avertissement sur « une ou plusieurs arêtes ».)</p>', g: 's22' },
      { t: 'Contre-exemple : pas un sous-graphe (une arête manque)', h: '<p>Sommets 1, 2, 3, 5, 6, mais avec les seules arêtes {1,3} et {5,6} : l’arête {2,3} a ses deux extrémités dans A et devrait être présente. Ce n’est ni un sous-graphe ni un graphe partiel.</p>', g: NEITHER, counter: true },
      { t: 'Contre-exemple : pas un sous-graphe, mais un graphe partiel', h: '<p>On garde les six sommets et on retire {4,5} : c’est un graphe partiel, pas un sous-graphe (A = V obligerait à garder toutes les arêtes).</p>', g: HV, counter: true }
    ],
    compare: [{ t: 'Graphe partiel et sous-graphe', cols: ['', 'Graphe partiel', 'Sous-graphe'], rows: [['Sommets', 'tous les sommets de G', 'un sous-ensemble A de V'], ['Arêtes', 'on peut en retirer une ou plusieurs', 'toutes les arêtes de G entre sommets de A'], ['Sur la diapo 22', '{1,3}, {1,4}, {2,3}, {5,6} (6 sommets)', '{1,3}, {2,3}, {5,6} (5 sommets)'], ['Ce qu’on choisit', 'les arêtes à retirer', 'les sommets à garder']] }],
    mistakes: [
      { tag: 'partiel-vs-sousgraphe', wrong: 'Pour un sous-graphe, on choisit des sommets et on garde seulement certaines arêtes entre eux.', right: 'Dans ce cours, un sous-graphe garde <b>toutes</b> les arêtes de G entre les sommets choisis (diapo 22). Retirer une arête entre sommets gardés donne autre chose.' },
      { tag: 'partiel-vs-sousgraphe', wrong: 'Un graphe partiel peut avoir moins de sommets que G.', right: 'Un graphe partiel garde <b>tous</b> les sommets et ne retire que des arêtes.' },
      { tag: 'induit', wrong: 'En supprimant un sommet, ses arêtes restent dans le sous-graphe.', right: 'Une arête n’appartient au sous-graphe que si <b>ses deux extrémités</b> sont dans A : supprimer 4 fait disparaître {1,4}, {3,4} et {4,5}.' },
      { tag: 'partiel-vs-sousgraphe', wrong: 'Graphe partiel et sous-graphe, c’est la même chose.', right: 'L’un choisit des <b>arêtes</b> à retirer (tous les sommets restent), l’autre choisit des <b>sommets</b> à garder (toutes les arêtes entre eux restent).' },
      { tag: 'partiel-vs-sousgraphe', wrong: 'On peut ajouter des arêtes pour obtenir un graphe partiel ou un sous-graphe.', right: 'Dans les deux cas, les arêtes de G′ sont des arêtes de G : on ne fait que retirer.' }
    ],
    alt: [
      '<p>Imaginez un réseau de routes. Un <b>graphe partiel</b> : toutes les villes existent encore, mais certaines routes sont coupées. Un <b>sous-graphe</b> : on ne s’intéresse qu’à certaines villes, et on garde toutes les routes qui les relient entre elles.</p>',
      '<p>Pour le sous-graphe sur A : écrivez la liste des arêtes de G, puis rayez toute arête dont au moins une extrémité n’est pas dans A. Ce qui reste est E(A).</p>',
      '<p>Un test mental : « Est-ce que j’ai le droit de mettre une arête de plus sans changer les sommets ? » Pour un graphe partiel, oui (tant que c’est une arête de G). Pour un sous-graphe, toutes les arêtes possibles sont déjà là.</p>'
    ],
    socratic: {
      warm: { id: 'n12.s0', type: 'choice', q: 'Un graphe G(V, E) est défini par…', options: ['un ensemble de sommets V et un ensemble d’arêtes E', 'un ensemble de sommets V seulement', 'un ensemble d’arêtes E et un degré maximum', 'un nombre de sommets et un nombre d’arêtes seulement'], answer: 0,
        counter: '<p>Cas plus simple : pour un triangle A–B–C, que valent V et E ?</p>', hints: ['<p>Relisez la définition de la diapo 8 : G = (V, E).</p>', '<p>Il faut savoir <i>quels</i> sommets et <i>quelles</i> arêtes, pas seulement combien.</p>'],
        ok: '<p>Exact. Si l’on modifie V ou E, on obtient un autre graphe : comment peut-on le faire en conservant un lien avec G ?</p>', explain: '<p>Un graphe est un couple G = (V, E) : un ensemble de sommets et un ensemble d’arêtes (diapo 8). Exemple : un triangle a V = {A, B, C} et E = {{A,B}, {B,C}, {C,A}}.</p>', restate: '<p>Redites avec vos mots ce que sont V et E.</p>' },
      steps: [
        { id: 'n12.s1', type: 'choice', g: 's22p', q: 'Le graphe de droite est obtenu à partir de G (diapo 22) en retirant les arêtes {3,4} et {4,5}, sans retirer de sommet. C’est…', options: ['Un graphe partiel de G', 'Un sous-graphe de G', 'Ni l’un ni l’autre', 'Un sous-graphe et un graphe partiel à la fois'], answer: 0,
          counter: '<p>Cas plus simple : dans un triangle, on retire une arête et on garde les trois sommets. Est-ce un graphe partiel ?</p>', hints: ['<p>Qu’a-t-on retiré : des sommets ou des arêtes ?</p>', '<p>Graphe partiel : on garde tous les sommets et on enlève des arêtes (diapo 22).</p>'],
          ok: '<p>Oui. Est-ce aussi un sous-graphe de G ?</p>', explain: '<p>Les six sommets sont conservés et seules des arêtes sont retirées : c’est un graphe partiel. Ce n’est pas un sous-graphe car, avec A = V, il faudrait garder toutes les arêtes de G. Exemple : un triangle privé d’une arête est un graphe partiel du triangle.</p>', restate: '<p>Redites ce qui caractérise un graphe partiel.</p>' },
        { id: 'n12.s2', type: 'choice', g: 's22s', q: 'Le graphe de droite a pour sommets {1, 2, 3, 5, 6} et pour arêtes {1,3}, {2,3}, {5,6}. Par rapport à G (diapo 22), c’est…', options: ['Un sous-graphe de G sur A = {1, 2, 3, 5, 6}', 'Un graphe partiel de G', 'Un graphe partiel et un sous-graphe à la fois', 'Ni l’un ni l’autre'], answer: 0,
          counter: '<p>Cas plus simple : dans un chemin A–B–C, si l’on supprime le sommet C, quelles arêtes restent ?</p>', hints: ['<p>Quel sommet manque ? Est-ce que toutes les arêtes de G entre les autres sommets sont présentes ?</p>', '<p>Listez les arêtes de G dont les deux extrémités sont dans A.</p>'],
          ok: '<p>Oui. Pourquoi n’est-ce pas un graphe partiel ?</p>', explain: '<p>Les arêtes de G entre sommets de A sont {1,3}, {2,3}, {5,6} : toutes sont présentes, donc c’est un sous-graphe. Ce n’est pas un graphe partiel car le sommet 4 a disparu. Exemple : dans A–B–C, supprimer C laisse le sous-graphe A–B.</p>', restate: '<p>Redites ce qui caractérise un sous-graphe.</p>' },
        { id: 'n12.s3', type: 'num', g: 's22', go: { hlV: { '3': 'hl', '4': 'hl', '5': 'hl' } }, q: 'Combien d’arêtes a le <b>sous-graphe de G sur A = {3, 4, 5}</b> (G : diapo 22) ?', answer: function (G) { return GR.inducedSubgraph(G, ['3', '4', '5']).edges.length; },
          counter: '<p>Cas plus simple : dans un triangle A–B–C, combien d’arêtes a le sous-graphe sur {A, B} ?</p>', hints: ['<p>Parcourez les 6 arêtes de G et gardez celles dont les deux extrémités sont dans {3, 4, 5}.</p>', '<p>Une arête dont une seule extrémité est dans A est exclue.</p>'],
          ok: '<p>Oui : {3,4} et {4,5}. Que se passerait-il avec A = {1, 3, 4} ?</p>', explain: '<p>Les arêtes de G avec leurs deux extrémités dans {3, 4, 5} sont {3,4} et {4,5}. Exemple : dans un triangle, le sous-graphe sur {A, B} a une seule arête, {A, B}.</p>', restate: '<p>Redites la règle pour obtenir E(A).</p>' },
        { id: 'n12.s4', type: 'choice', g: NEITHER, q: 'G est le graphe de la diapo 22. H a pour sommets {1, 2, 3, 5, 6} et pour arêtes {1,3} et {5,6} seulement. H est…', options: ['Un sous-graphe de G', 'Un graphe partiel de G', 'Ni un sous-graphe ni un graphe partiel de G', 'Un sous-graphe et un graphe partiel à la fois'], answer: 2,
          counter: '<p>Cas plus simple : dans un triangle A–B–C, le graphe de sommets {A, B} sans arête est-il un sous-graphe ?</p>', hints: ['<p>Il manque le sommet 4 : est-ce un graphe partiel ?</p>', '<p>Pour un sous-graphe, toutes les arêtes de G entre 1, 2, 3, 5, 6 doivent être présentes : laquelle manque ?</p>'],
          ok: '<p>Bien. Quelle modification en ferait un sous-graphe ?</p>', explain: '<p>Pas un graphe partiel : le sommet 4 est absent. Pas un sous-graphe : l’arête {2,3} a ses deux extrémités dans A mais n’est pas dans H. Exemple : dans un triangle, {A, B} sans l’arête {A, B} n’est pas un sous-graphe.</p>', restate: '<p>Reformulez les deux tests (sommets, arêtes) pour qualifier un graphe H.</p>' },
        { id: 'n12.s5', type: 'text', q: 'Expliquez avec vos mots la différence entre un graphe partiel et un sous-graphe de G, avec un exemple pour chacun.', expect: ['Graphe partiel : tous les sommets de G, on enlève des arêtes', 'Sous-graphe : un sous-ensemble A de sommets et toutes les arêtes de G entre sommets de A', 'Exemple : retirer {3,4} et {4,5} (partiel) ; supprimer le sommet 4 et ses arêtes (sous-graphe)'],
          counter: '<p>Sur la diapo 22, que fait-on au sommet 4 dans chacun des deux exemples ?</p>', hints: ['<p>L’un touche aux arêtes, l’autre aux sommets.</p>', '<p>Pensez au « sommet supprimé » : que deviennent ses arêtes ?</p>'],
          ok: '<p>Bien. Peut-on appliquer les deux opérations de suite ?</p>', explain: '<p>Graphe partiel : on garde tous les sommets de G, on enlève des arêtes. Sous-graphe : on garde un sous-ensemble A de sommets et toutes les arêtes de G entre eux. Exemple : sur la diapo 22, retirer {3,4} et {4,5} donne un graphe partiel ; supprimer le sommet 4 (avec ses arêtes) donne le sous-graphe sur {1, 2, 3, 5, 6}.</p>', restate: '<p>Reformulez : qu’est-ce qu’on choisit dans chaque cas, des sommets ou des arêtes ?</p>' }
      ],
      verify: { gen: 'subgraph', level: 2 }
    },
    feynman: {
      topic: 'Graphe partiel et sous-graphe',
      prompt: 'Expliquez à un débutant la différence entre un graphe partiel et un sous-graphe d’un graphe G, avec un exemple et un contre-exemple.',
      must: ['Graphe partiel : on garde tous les sommets et on enlève une ou plusieurs arêtes (diapo 22)', 'Sous-graphe : un sous-ensemble A de sommets avec toutes les arêtes de G ayant leurs deux extrémités dans A', 'Un exemple de chacun (diapo 22)', 'Un contre-exemple (un graphe qui n’est ni l’un ni l’autre, ou une arête manquante entre sommets gardés)', 'Supprimer un sommet supprime ses arêtes'],
      pitfalls: ['Croire qu’un sous-graphe peut perdre des arêtes entre sommets gardés', 'Croire qu’un graphe partiel peut perdre des sommets', 'Confondre les deux notions'],
      beginner: ['Si je supprime un sommet, que deviennent ses arêtes ?', 'Peut-on retirer une arête dans un sous-graphe ?', 'Un graphe peut-il être à la fois partiel et sous-graphe ?', 'Pourquoi appelle-t-on « partiel » un graphe qui garde tous les sommets ?'],
      model: '<p>Un <b>graphe partiel</b> de G garde <b>tous les sommets</b> de G et ne garde que certaines arêtes (on en retire une ou plusieurs). Un <b>sous-graphe</b> de G garde <b>certains sommets</b> A et <b>toutes les arêtes de G</b> qui relient deux sommets de A. Exemple (diapo 22) : retirer {3,4} et {4,5} donne un graphe partiel ; supprimer le sommet 4 donne un sous-graphe sur {1, 2, 3, 5, 6} (ses arêtes {1,4}, {3,4}, {4,5} disparaissent avec lui). Contre-exemple : garder les sommets 1, 2, 3, 5, 6 mais oublier l’arête {2,3} ne donne ni l’un ni l’autre.</p>'
    },
    recap: {
      key: ['Graphe partiel G′ = (V, E′) : mêmes sommets, on enlève une ou plusieurs arêtes (diapo 22).', 'Sous-graphe G′ = (A, E(A)) : A ⊆ V et E(A) = toutes les arêtes de G ayant leurs deux extrémités dans A (diapo 22).', 'Dans ce cours, « sous-graphe » = sous-graphe induit.', 'Supprimer un sommet supprime toutes ses arêtes.'],
      defs: [{ t: 'Graphe partiel', d: 'G′ = (V, E′) obtenu en enlevant une ou plusieurs arêtes à G(V, E).', slide: '22' }, { t: 'Sous-graphe', d: 'G′ = (A, E(A)) avec A ⊆ V et E(A) formé de toutes les arêtes de G ayant leurs deux extrémités dans A.', slide: '22' }],
      thms: [],
      formulas: []
    },
    qs: [
      qb.choice('n12.q1', 1, 'D’après la diapo 22, un graphe partiel de G(V, E) est obtenu…', ['en enlevant une ou plusieurs arêtes de G (tous les sommets sont gardés)', 'en enlevant un ou plusieurs sommets de G', 'en ajoutant des arêtes à G', 'en gardant seulement les sommets de degré maximum'], 0, '<p>Un graphe partiel G′ = (V, E′) garde l’ensemble V des sommets et retire des arêtes (diapo 22).</p>', { src: 'course', slide: '22', tag: 'partiel-vs-sousgraphe', hints: ['Relisez la première puce de la diapo 22.'] }),
      qb.choice('n12.q2', 1, 'D’après la diapo 22, E(A), l’ensemble des arêtes d’un sous-graphe (A, E(A)) de G, est formé…', ['de toutes les arêtes de G ayant leurs deux extrémités dans A', 'de certaines arêtes de G choisies librement', 'de toutes les arêtes de G ayant au moins une extrémité dans A', 'des arêtes de G ayant leurs deux extrémités hors de A'], 0, '<p>E(A) contient <b>toutes</b> les arêtes de G dont les <b>deux</b> extrémités sont dans A (diapo 22).</p>', { src: 'course', slide: '22', tag: 'induit', hints: ['Relisez la deuxième puce de la diapo 22.'] }),
      qb.text('n12.q3', 1, 'Expliquez avec vos mots la différence entre un graphe partiel et un sous-graphe.', '<p>Un graphe partiel garde tous les sommets de G et enlève une ou plusieurs arêtes. Un sous-graphe garde un sous-ensemble A de sommets et toutes les arêtes de G dont les deux extrémités sont dans A. Sur la diapo 22, retirer {3,4} et {4,5} donne un graphe partiel ; supprimer le sommet 4 donne un sous-graphe.</p>', ['Graphe partiel : tous les sommets gardés, des arêtes retirées', 'Sous-graphe : un sous-ensemble A de sommets', 'Sous-graphe : toutes les arêtes de G entre sommets de A', 'Un exemple tiré de la diapo 22'], { src: 'course', slide: '22', tag: 'partiel-vs-sousgraphe', hints: ['Reprenez les deux puces de la diapo 22.'] }),
      qb.num('n12.q4', 2, 'Combien d’arêtes a le sous-graphe de G (diapo 22) sur A = {1, 2, 3, 4} ?', function (G) { return inducedCount(G, ['1', '2', '3', '4']); }, function (G) { return '<p>Arêtes de G avec leurs deux extrémités dans {1, 2, 3, 4} : {1,3}, {1,4}, {2,3}, {3,4}, soit ' + inducedCount(G, ['1', '2', '3', '4']) + '. Les arêtes {4,5} et {5,6} ont une extrémité hors de A.</p>'; }, { graph: 's22', src: 'course', slide: '22', tag: 'induit', hints: ['Gardez les arêtes dont les deux extrémités sont dans A.'] }),
      qb.choice('n12.q5', 2, 'À gauche G (diapo 22), à droite H. H est…', ['Un graphe partiel de G', 'Un sous-graphe de G', 'Un graphe partiel et un sous-graphe de G', 'Ni un graphe partiel ni un sous-graphe de G'], 0, '<p>H a les six sommets de G et seulement des arêtes de G ({1,3}, {1,4}, {2,3}, {5,6}) : c’est un graphe partiel. Ce n’est pas un sous-graphe : avec A = V, il faudrait toutes les arêtes de G, dont {3,4} et {4,5}.</p>', { graph: 's22', graph2: 's22p', src: 'course', slide: '22', tag: 'partiel-vs-sousgraphe', hints: ['Comparez les sommets de H et de G, puis les arêtes.'] }),
      qb.tf('n12.q6', 2, 'Un graphe partiel de G a toujours moins de sommets que G.', false, ['Un graphe partiel garde tous les sommets de G et ne retire que des arêtes.', 'Parce qu’on supprime toujours des sommets de degré 1.', 'Parce que G n’a pas de sommet isolé.', 'Parce qu’un sous-graphe ne peut pas avoir d’arêtes.'], 0, '<p>Un graphe partiel G′ = (V, E′) a le même ensemble V de sommets que G (diapo 22). C’est le <i>sous-graphe</i> qui peut avoir moins de sommets.</p>', { src: 'course', slide: '22', tag: 'partiel-vs-sousgraphe', hints: ['Relisez : « enlevant une ou plusieurs arêtes ».'] }),
      qb.edges('n12.q7', 2, 'Écrivez les arêtes du <b>sous-graphe de G (diapo 22) sur A = {2, 3, 4, 5}</b>.', function (g) {
        var A = ['2', '3', '4', '5'], want = {}, got = {}, i, e, k;
        GR.inducedSubgraph(G22, A).edges.forEach(function (x) { want[GR.pairKey(x.u, x.v)] = true; });
        for (i = 0; i < g.edges.length; i++) {
          e = g.edges[i]; k = GR.pairKey(e.u, e.v);
          if (A.indexOf(e.u) < 0 || A.indexOf(e.v) < 0) return { ok: false, msg: 'L’arête ' + e.u + '-' + e.v + ' a une extrémité hors de A.' };
          if (!want[k]) return { ok: false, msg: 'L’arête ' + e.u + '-' + e.v + ' n’existe pas dans G.' };
          got[k] = true;
        }
        var missing = Object.keys(want).filter(function (x) { return !got[x]; }).length;
        if (missing) return { ok: false, msg: missing + ' arête(s) de G entre sommets de A ne sont pas écrites : un sous-graphe contient TOUTES les arêtes de G ayant leurs deux extrémités dans A.' };
        return { ok: true };
      }, '<p>Arêtes de G avec leurs deux extrémités dans {2, 3, 4, 5} : {2,3}, {3,4}, {4,5}. Les arêtes {1,3}, {1,4} (sommet 1) et {5,6} (sommet 6) sont exclues.</p>', { graph: 's22', sample: '2-3, 3-4, 4-5', tag: 'induit', hints: ['Parcourez les 6 arêtes de G une par une.', 'Gardez celles dont les deux extrémités sont dans A.'] }),
      qb.tf('n12.q8', 2, 'Le graphe G lui-même est un sous-graphe de G.', true, ['Avec A = V, E(A) est l’ensemble de toutes les arêtes de G : on retrouve G.', 'Parce que G a au moins un sommet isolé.', 'Parce qu’un sous-graphe a toujours le même nombre d’arêtes que G.', 'C’est faux : un sous-graphe a toujours moins de sommets que G.'], 0, '<p>A est un <i>sous-ensemble</i> de V : il peut être V tout entier. Alors E(A) est formé de toutes les arêtes de G : le sous-graphe est G.</p>', { src: 'extra', tag: 'induit', hints: ['Peut-on prendre A = V ?'] }),
      qb.num('n12.q9', 3, 'Combien d’arêtes a le sous-graphe de G (diapo 22) sur A = {3, 4, 5, 6} ?', function (G) { return inducedCount(G, ['3', '4', '5', '6']); }, function (G) { return '<p>Arêtes de G dans {3, 4, 5, 6} : {3,4}, {4,5}, {5,6}, soit ' + inducedCount(G, ['3', '4', '5', '6']) + '. {1,3}, {1,4}, {2,3} touchent 1 ou 2, hors de A.</p>'; }, { graph: 's22', tag: 'induit', hints: ['Listez les arêtes de G dont les deux extrémités sont dans A.'] }),
      qb.choice('n12.q10', 3, 'Un réseau routier relie des villes par des routes. Une inondation coupe deux routes, mais aucune ville n’est détruite. Le réseau restant est…', ['un graphe partiel du réseau initial', 'un sous-graphe du réseau initial', 'à la fois un graphe partiel et un sous-graphe', 'ni l’un ni l’autre'], 0, '<p>Villes = sommets, routes = arêtes. Toutes les villes sont gardées et deux arêtes sont retirées : c’est un graphe partiel. Ce n’est pas un sous-graphe : avec toutes les villes, il faudrait garder toutes les routes.</p>', { transfer: true, tag: 'partiel-vs-sousgraphe', hints: ['Modélisez : villes = sommets, routes = arêtes.', 'Retire-t-on des sommets ou des arêtes ?'] }),
      qb.edges('n12.q11', 3, 'Écrivez la liste des arêtes d’un <b>graphe partiel de G</b> (diapo 22) qui a <b>exactement 5 arêtes</b> et qui reste <b>connexe</b>.', function (g) {
        var vs = ['1', '2', '3', '4', '5', '6'], i, e, ok = {};
        if (!hasAll(g, vs)) return { ok: false, msg: 'Un graphe partiel garde tous les sommets de G : il doit avoir les six sommets 1 à 6.' };
        G22.edges.forEach(function (x) { ok[GR.pairKey(x.u, x.v)] = true; });
        for (i = 0; i < g.edges.length; i++) { e = g.edges[i]; if (!ok[GR.pairKey(e.u, e.v)]) return { ok: false, msg: 'L’arête ' + e.u + '-' + e.v + ' n’existe pas dans G.' }; }
        if (!GR.isSimple(g)) return { ok: false, msg: 'Une arête est écrite deux fois.' };
        if (g.edges.length !== 5) return { ok: false, msg: 'Votre graphe a ' + g.edges.length + ' arête(s) ; il en faut exactement 5.' };
        if (!GR.isConnected(g)) return { ok: false, msg: 'Le graphe n’est pas connexe.' };
        return { ok: true };
      }, '<p>G a 6 arêtes ; il suffit d’en retirer une sans déconnecter le graphe. {1,3}, {1,4}, {3,4} forment un triangle : on peut en retirer une, par exemple {3,4}. Il reste {1,3}, {1,4}, {2,3}, {4,5}, {5,6}. (Retirer {2,3}, {4,5} ou {5,6} déconnecterait le graphe.)</p>', { graph: 's22', sample: '1-3, 1-4, 2-3, 4-5, 5-6', challenge: true, tag: 'partiel-vs-sousgraphe', hints: ['G a 6 arêtes : laquelle peut-on retirer sans casser la connexité ?', 'Cherchez une arête qui appartient à un cycle.'] })
    ]
  });
  })();
  /* ================= n13 ================= */
  (function () {
    var P4 = mk('ABCD', ['AB', 'BC', 'CD']), TT = mk('ABCDEF', ['AB', 'BC', 'CA', 'DE', 'EF', 'FD']), BOW = mk('ABCDE', ['AB', 'BC', 'CA', 'CD', 'DE', 'EC']), K5 = GS.get('k5');
    var OPTS = ['Il admet un cycle eulérien', 'Il admet une chaîne eulérienne (non fermée) mais pas de cycle eulérien', 'Il n’admet ni cycle eulérien ni chaîne eulérienne'];
    function kindIdx(G) { var e = GR.euler(G); return e.kind === 'cycle' ? 0 : e.kind === 'chain' ? 1 : 2; }
    function oddTxt(G) { var o = GR.oddVertices(G); return o.length ? U.set(o) : 'aucun'; }
  GF.content.add({
    id: 'n13', title: 'Parcours eulériens', short: 'Parcours eulériens', slides: '23–25', prereqs: ['n04', 'n08', 'n09'],
    objectives: [
      'Distinguer le parcours eulérien (chaque arête une seule fois) du parcours hamiltonien (chaque sommet une seule fois).',
      'Définir graphe eulérien (cycle eulérien) et semi-eulérien (chaîne eulérienne), et savoir ce que veut dire « sans lever le crayon ».',
      'Appliquer les deux théorèmes d’Euler : décider, en comptant les sommets de degré impair d’un graphe connexe, s’il admet un cycle ou une chaîne eulérienne.',
      'Modéliser un problème de tracé (diapo 25) par un graphe et conclure, ou construire un parcours eulérien quand il existe.'
    ],
    course: [
      { k: 'def', slide: '23', t: 'Deux problèmes de parcours', h: '<p>La diapo 23 oppose deux questions et leur modèle :</p><ul><li><b>Inspecter chaque liaison</b> → <b>parcours eulérien</b> : utiliser chaque arête une seule fois.</li><li><b>Visiter chaque site</b> → <b>parcours hamiltonien</b> : visiter chaque sommet une seule fois.</li></ul><p>Cette notion traite le parcours eulérien ; le parcours hamiltonien est vu à la notion suivante (diapos 26 à 28).</p>' },
      { k: 'def', slide: '24', t: 'Graphe eulérien', h: '<p>On dit qu’un graphe est <b>eulérien</b> s’il est possible de trouver un <b>cycle</b> passant une et une seule fois par <b>toutes les arêtes</b>.</p>', g: 'k5' },
      { k: 'def', slide: '24', t: 'Graphe semi-eulérien', h: '<p>On dit qu’un graphe est <b>semi-eulérien</b> s’il est possible de trouver une <b>chaîne</b> passant une et une seule fois par toutes les arêtes.</p>', g: P4, go: { walk: { seq: ['A', 'B', 'C', 'D'], numbers: true } } },
      { k: 'def', slide: '24', t: 'Sans lever le crayon', h: '<p>Plus simplement, on peut dire qu’un graphe est eulérien (ou semi-eulérien) s’il est possible de dessiner le graphe <b>sans lever le crayon</b>.</p>' },
      { k: 'thm', slide: '24', t: 'Théorème d’Euler (cycle)', h: '<p>Un graphe <b>connexe</b> <i>G</i> admet un <b>cycle eulérien</b> si et seulement si <b>tous ses sommets sont de degré pair</b>.</p>', g: K5, go: { showDeg: true } },
      { k: 'thm', slide: '24', t: 'Théorème d’Euler (chaîne)', h: '<p>Un graphe <b>connexe</b> <i>G</i> admet une <b>chaîne eulérienne</b> (d’extrémités <i>u</i> et <i>v</i>) si et seulement si il existe <b>exactement deux sommets de degré impair</b> (<i>u</i> et <i>v</i>).</p>', g: P4, go: { showDeg: true } },
      { k: 'q', slide: '25', t: 'Application : les 16 segments', h: '<p>« Est-il possible de tracer une courbe, sans lever le crayon, qui coupe chacun des 16 segments de la figure suivante exactement une fois ? » La figure est un rectangle découpé en 5 pièces : deux en haut et trois en bas. La diapo ne donne ni modèle ni réponse : voir ci-dessous.</p>' },
      { k: 'warn', slide: '24', t: 'Hypothèse de connexité et sommets isolés', h: '<p>Les deux théorèmes supposent G <b>connexe</b>. Le PDF ne dit pas comment traiter un graphe ayant des sommets isolés (qui ne portent aucune arête, donc ne gênent pas un parcours qui utilise toutes les arêtes). L’application, plus prudente, exige la connexité du graphe : un sommet isolé le rend non connexe. Le graphe à deux composantes (par exemple deux triangles) montre pourquoi l’hypothèse compte : tous ses degrés sont pairs, et pourtant il n’a pas de cycle eulérien.</p>', g: TT, go: { showDeg: true } },
      { k: 'warn', slide: '24', t: 'Semi-eulérien : chaîne non fermée', h: '<p>La diapo parle d’« une chaîne » sans dire si elle est fermée. Comme le second théorème impose deux sommets de degré impair <i>u</i> et <i>v</i> comme extrémités, la chaîne est <b>non fermée</b> : un graphe à tous les degrés pairs est eulérien (cycle), pas « semi-eulérien » au sens du théorème.</p>' },
      { k: 'warn', slide: '25', t: 'Modélisation non donnée', h: '<p>La diapo 25 pose la question des 16 segments sans modèle ni réponse. <b>Hors cours :</b> on prend les régions (5 pièces + l’extérieur) comme sommets et chaque segment comme une arête entre les deux régions qu’il sépare : 6 sommets, 16 arêtes. Quatre sommets sont de degré impair (l’extérieur : 9 ; trois pièces : 5), donc il n’y a pas de chaîne eulérienne et le tracé est impossible.</p>', g: 's25dual', go: { showDeg: true } },
      { k: 'extra', t: 'Pourquoi des degrés pairs ? (hors diapo)', h: '<p>Dans un cycle eulérien, chaque fois qu’on <i>arrive</i> en un sommet par une arête, on <i>repart</i> par une autre : les arêtes d’un sommet sont utilisées deux par deux, donc son degré est pair (le sommet de départ est aussi « quitté » au début et « rejoint » à la fin). Dans une chaîne non fermée, seuls le départ et l’arrivée ont un nombre impair d’arêtes utilisées. C’est l’idée de la condition nécessaire ; la réciproque (suffisance) est le contenu difficile du théorème.</p>' },
      { k: 'extra', t: 'Compter les sommets de degré impair (hors diapo)', h: '<p>Le nombre de sommets de degré impair est toujours <b>pair</b> (corollaire de la somme des degrés, diapo 13–14). Pour un graphe connexe il n’y a donc que trois cas : <b>0</b> impair → cycle eulérien ; <b>2</b> impairs → chaîne eulérienne seulement ; <b>4 ou plus</b> → ni l’un ni l’autre. Sur le graphe de la diapo 10 : degrés 2, 3, 3, 2, 3, 1 ; impairs B, C, E, F : quatre, donc ni cycle ni chaîne eulérienne.</p>', g: 's10', go: { showDeg: true, hlV: { B: 'hl', C: 'hl', E: 'hl', F: 'hl' } } },
      { k: 'extra', t: 'Les sept ponts de Königsberg (hors PDF)', h: '<p>Le problème classique d’Euler se modélise par un graphe à 4 sommets (rives et îles) et 7 arêtes (ponts, deux paires étant parallèles) : les degrés sont 5, 3, 3, 3. Quatre sommets de degré impair : il n’existe pas de promenade qui emprunte chaque pont exactement une fois. (Le graphe a des arêtes multiples ; les théorèmes de la diapo 24 sont énoncés sans préciser qu’ils s’appliquent aux multigraphes.)</p>', g: 'konigsberg', go: { showDeg: true } }
    ],
    guided: [
      { h: '<p>Pour décider si un graphe connexe a un parcours eulérien, il suffit de compter ses sommets de degré <b>impair</b>. Essayons sur le graphe de la diapo 10.</p>', g: 's10', go: { showDeg: true }, ask: 'Combien de sommets de degré impair ? Quelle conclusion ?', reveal: '<p>Degrés : A 2, B 3, C 3, D 2, E 3, F 1. Impairs : B, C, E, F, soit 4. Ni 0 ni 2 : le graphe (connexe) n’admet <b>ni cycle ni chaîne eulérienne</b>.</p>' },
      { h: '<p>Le chemin A–B–C–D n’a que des sommets de degré 1 ou 2.</p>', g: P4, go: { showDeg: true }, ask: 'Combien de sommets de degré impair ? Existe-t-il un parcours eulérien, et lequel ?', reveal: '<p>Degrés 1, 2, 2, 1 : exactement deux sommets impairs, A et D. Il y a donc une <b>chaîne eulérienne</b> d’extrémités A et D : A–B–C–D. Pas de cycle (il y a des sommets impairs).</p>' },
      { h: '<p>Dans K<sub>5</sub> (diapo 20), chaque sommet est adjacent aux 4 autres.</p>', g: 'k5', go: { showDeg: true }, ask: 'Que dit le théorème pour K₅ ?', reveal: '<p>Tous les degrés valent 4 (pairs) et le graphe est connexe : il admet un <b>cycle eulérien</b>, qui passe par les 10 arêtes. K<sub>n</sub> est eulérien pour tout n impair (degré n − 1 pair).</p>' },
      { h: '<p>Deux triangles séparés : tous les degrés valent 2.</p>', g: TT, go: { showDeg: true }, ask: 'Ce graphe a-t-il un cycle eulérien ?', reveal: '<p>Non : le théorème exige que le graphe soit <b>connexe</b>. Ici il a deux composantes, et un cycle d’un seul tenant ne peut pas utiliser les arêtes de deux composantes. Tous les degrés pairs ne suffisent pas.</p>' },
      { h: '<p>Revenons à la question de la diapo 25. Le modèle (régions = sommets, segments = arêtes) donne le graphe ci-dessous, avec 16 arêtes.</p>', g: 's25dual', go: { showDeg: true }, ask: 'Peut-on tracer la courbe demandée ?', reveal: '<p>Degrés : extérieur 9, a 5, b 5, c 4, d 5, e 4. Quatre sommets impairs (X, a, b, d) : pas de chaîne eulérienne, donc <b>le tracé est impossible</b>.</p>' }
    ],
    examples: [
      { t: 'K₅ : un cycle eulérien', h: '<p>Tous les degrés valent 4, le graphe est connexe : par exemple 1–2–3–4–5–1–3–5–2–4–1 passe une fois par chacune des 10 arêtes.</p>', g: 'k5', go: { showDeg: true } },
      { t: 'Le chemin A–B–C–D : une chaîne eulérienne', h: '<p>Deux sommets impairs (A et D) : chaîne eulérienne A–B–C–D.</p>', g: P4, go: { showDeg: true, walk: { seq: ['A', 'B', 'C', 'D'], numbers: true } } },
      { t: 'Un nœud papillon : cycle eulérien', h: '<p>Degrés 2, 2, 4, 2, 2 : tous pairs. Le cycle C–A–B–C–D–E–C passe une fois par chaque arête.</p>', g: BOW, go: { showDeg: true, walk: { seq: ['C', 'A', 'B', 'C', 'D', 'E', 'C'], numbers: true } } },
      { t: 'Contre-exemple : le graphe de la diapo 10', h: '<p>Quatre sommets de degré impair (B, C, E, F) : ni cycle ni chaîne eulérienne.</p>', g: 's10', go: { showDeg: true }, counter: true },
      { t: 'Contre-exemple : tous les degrés pairs, mais pas connexe', h: '<p>Deux triangles disjoints : degrés tous égaux à 2, mais pas de cycle eulérien car le graphe n’est pas connexe.</p>', g: TT, go: { showDeg: true }, counter: true },
      { t: 'Contre-exemple : le cube (diapo 28)', h: '<p>Chaque sommet est de degré 3 (impair) : 8 sommets impairs. Le cube n’est donc pas eulérien, ce que demande de montrer la diapo 28 (en plus d’être hamiltonien).</p>', g: 's28a', go: { showDeg: true }, counter: true }
    ],
    compare: [{ t: 'Selon le nombre de sommets de degré impair (graphe connexe)', cols: ['Sommets de degré impair', 'Conclusion', 'Exemple'], rows: [['0', 'cycle eulérien (graphe eulérien)', 'K₅ ; nœud papillon'], ['2 (u et v)', 'chaîne eulérienne d’extrémités u et v (semi-eulérien)', 'chemin A–B–C–D'], ['4 ou plus', 'ni cycle ni chaîne eulérienne', 'graphe de la diapo 10 ; cube ; modèle de la diapo 25']] }],
    mistakes: [
      { tag: 'euler-connexite', wrong: 'Si tous les sommets sont de degré pair, le graphe a un cycle eulérien.', right: 'Il faut aussi que le graphe soit <b>connexe</b> (diapo 24) : deux triangles disjoints ont tous leurs degrés pairs mais pas de cycle eulérien.' },
      { tag: 'euler-conditions', wrong: 'Un parcours eulérien passe une seule fois par chaque sommet.', right: 'C’est le parcours <b>hamiltonien</b> (sommets). Le parcours eulérien utilise chaque <b>arête</b> une seule fois, en repassant éventuellement par les mêmes sommets.' },
      { tag: 'euler-conditions', wrong: 'Une chaîne eulérienne existe dès qu’il y a au moins deux sommets de degré impair.', right: 'Il faut <b>exactement</b> deux sommets de degré impair (diapo 24). Avec 4 ou plus, il n’y en a pas.' },
      { tag: 'euler-conditions', wrong: 'Un graphe avec un seul sommet de degré impair peut avoir une chaîne eulérienne.', right: 'Le nombre de sommets de degré impair est toujours pair : un seul sommet impair est impossible.' },
      { tag: 'euler-conditions', wrong: 'Un graphe semi-eulérien admet un cycle eulérien.', right: 'Semi-eulérien : chaîne eulérienne <b>non fermée</b>, d’extrémités les deux sommets impairs ; il n’y a alors pas de cycle eulérien.' }
    ],
    alt: [
      '<p>Pensez à dessiner une figure d’un seul trait, sans repasser sur un trait déjà tracé. Chaque fois que vous passez par un carrefour, vous arrivez par un trait et repartez par un autre : les traits d’un carrefour vont par <b>paires</b>, sauf au départ et à l’arrivée. Si le trait doit revenir au départ, tous les carrefours ont un nombre pair de traits ; sinon, exactement deux (départ et arrivée) en ont un nombre impair.</p>',
      '<p>Procédure : (1) le graphe est-il connexe ? (2) calculez les degrés, (3) comptez les degrés impairs : 0 → cycle ; 2 → chaîne entre ces deux sommets ; plus → impossible.</p>',
      '<p>Pour construire un parcours : commencez en un sommet impair s’il y en a (sinon n’importe où) et avancez en évitant de « couper » le graphe en laissant des arêtes de l’autre côté d’un pont que vous venez de franchir.</p>'
    ],
    socratic: {
      warm: { id: 'n13.s0', type: 'choice', q: 'Dans un graphe, que peut-on dire du nombre de sommets de degré impair ?', options: ['Il est toujours pair', 'Il est toujours impair', 'Il peut valoir n’importe quel entier', 'Il est toujours égal à 2'], answer: 0,
        counter: '<p>Cas plus simple : la somme des degrés vaut 2|E|, un nombre pair. Combien de nombres impairs faut-il additionner pour obtenir une somme paire ?</p>', hints: ['<p>Rappelez-vous le théorème de la diapo 13 : Σ d(v) = 2|E|.</p>', '<p>Une somme de nombres impairs est paire seulement si on en a un nombre pair.</p>'],
        ok: '<p>Exact. Le théorème d’Euler s’appuie sur les sommets de degré impair : combien peut-il y en avoir si un parcours existe ?</p>', explain: '<p>Σ d(v) = 2|E| est pair. Les degrés pairs contribuent une somme paire ; pour que le total reste pair, il faut un nombre pair de degrés impairs. Exemple : le chemin A–B–C–D a deux sommets impairs (A et D).</p>', restate: '<p>Redites pourquoi le nombre de sommets impairs est pair.</p>' },
      steps: [
        { id: 'n13.s1', type: 'set', g: 's10', go: { showDeg: true }, q: 'Donnez l’ensemble des sommets de <b>degré impair</b> du graphe de la diapo 10.', answer: function (G) { return GR.oddVertices(G); },
          counter: '<p>Cas plus simple : dans un triangle A–B–C, quels sommets sont de degré impair ?</p>', hints: ['<p>Calculez d’abord le degré de chaque sommet.</p>', '<p>Gardez ceux dont le degré est impair (1, 3, 5…).</p>'],
          ok: '<p>Oui : B, C, E, F. Combien y en a-t-il, et que dit le théorème d’Euler ?</p>', explain: '<p>Degrés : A 2, B 3, C 3, D 2, E 3, F 1. Les degrés impairs sont ceux de B, C, E et F. Exemple : dans un triangle, tous les degrés valent 2 : aucun sommet impair.</p>', restate: '<p>Redites ce qu’est un sommet de degré impair.</p>' },
        { id: 'n13.s2', type: 'choice', g: 's10', q: 'Le graphe de la diapo 10 est connexe et a 4 sommets de degré impair. Il admet…', options: ['Un cycle eulérien', 'Une chaîne eulérienne mais pas de cycle', 'Ni cycle ni chaîne eulérienne', 'Les deux'], answer: 2,
          counter: '<p>Cas plus simple : un chemin A–B–C–D a 2 sommets impairs. Que permet-il ?</p>', hints: ['<p>Relisez les deux théorèmes de la diapo 24 : combien de sommets impairs pour un cycle ? pour une chaîne ?</p>', '<p>Ici il y en a 4 : est-ce 0 ? est-ce exactement 2 ?</p>'],
          ok: '<p>Oui. Que faudrait-il changer pour obtenir une chaîne eulérienne ?</p>', explain: '<p>Cycle : 0 sommet impair. Chaîne : exactement 2. Avec 4 sommets impairs, aucun des deux théorèmes ne s’applique : pas de parcours eulérien. Exemple : le chemin A–B–C–D, avec 2 sommets impairs, a une chaîne eulérienne.</p>', restate: '<p>Redites les trois cas selon le nombre de sommets impairs.</p>' },
        { id: 'n13.s3', type: 'choice', g: P4, go: { showDeg: true }, q: 'Le chemin A–B–C–D (degrés 1, 2, 2, 1) admet…', options: ['Un cycle eulérien', 'Une chaîne eulérienne d’extrémités A et D, mais pas de cycle', 'Ni l’un ni l’autre', 'Un cycle eulérien d’extrémités A et D'], answer: 1,
          counter: '<p>Cas plus simple : dessinez A–B–C–D d’un seul trait. Où commencez-vous, où finissez-vous ?</p>', hints: ['<p>Quels sommets sont de degré impair ?</p>', '<p>Exactement deux sommets impairs : que dit le second théorème ?</p>'],
          ok: '<p>Oui. Et si l’on ajoutait l’arête D–A ?</p>', explain: '<p>Les sommets impairs sont A et D : exactement deux, donc il y a une chaîne eulérienne d’extrémités A et D (A–B–C–D). Il n’y a pas de cycle, car tous les degrés ne sont pas pairs. Exemple : en ajoutant {D, A} on obtient un carré dont tous les degrés valent 2 : cycle eulérien.</p>', restate: '<p>Redites pourquoi la chaîne commence et finit en des sommets de degré impair.</p>' },
        { id: 'n13.s4', type: 'choice', g: TT, go: { showDeg: true }, q: 'Deux triangles disjoints : tous les sommets sont de degré 2. Ce graphe admet-il un cycle eulérien ?', options: ['Oui : tous les degrés sont pairs', 'Non : le graphe n’est pas connexe', 'Oui : chaque triangle est un cycle', 'Non : il y a des sommets de degré impair'], answer: 1,
          counter: '<p>Cas plus simple : peut-on dessiner deux triangles séparés d’un seul trait, sans lever le crayon ?</p>', hints: ['<p>Relisez les hypothèses du théorème de la diapo 24 : « Un graphe connexe… ».</p>', '<p>Un cycle est d’un seul tenant : peut-il passer d’un triangle à l’autre ?</p>'],
          ok: '<p>Bien vu. Quelle hypothèse du théorème est ici en défaut ?</p>', explain: '<p>Le théorème suppose le graphe <b>connexe</b> ; ici il a deux composantes, et un cycle ne peut pas relier des arêtes de deux composantes. Exemple : deux triangles ne se dessinent pas sans lever le crayon.</p>', restate: '<p>Redites les deux conditions pour un cycle eulérien : connexité et degrés pairs.</p>' },
        { id: 'n13.s5', type: 'text', q: 'Expliquez comment décider, pour un graphe donné, s’il admet un cycle eulérien, une chaîne eulérienne, ou aucun des deux.', expect: ['Vérifier que le graphe est connexe', 'Aucun sommet de degré impair : cycle eulérien', 'Exactement deux sommets de degré impair : chaîne eulérienne entre ces deux sommets ; plus de deux : ni l’un ni l’autre'],
          counter: '<p>Appliquez votre méthode au chemin A–B–C–D, puis au graphe de la diapo 10.</p>', hints: ['<p>Trois cas selon le nombre de sommets de degré impair.</p>', '<p>N’oubliez pas la condition de connexité.</p>'],
          ok: '<p>Bien. Appliquez maintenant cette méthode à la question des 16 segments (diapo 25).</p>', explain: '<p>On vérifie d’abord que le graphe est connexe, puis on compte les sommets de degré impair : 0 → cycle eulérien ; exactement 2 → chaîne eulérienne dont les extrémités sont ces deux sommets ; 4 ou plus → ni l’un ni l’autre. Exemple : le chemin A–B–C–D a 2 sommets impairs : chaîne eulérienne A–B–C–D.</p>', restate: '<p>Reformulez la méthode en trois lignes.</p>' }
      ],
      verify: { gen: 'euler', level: 2 }
    },
    feynman: {
      topic: 'Parcours eulériens',
      prompt: 'Expliquez à un débutant ce qu’est un graphe eulérien ou semi-eulérien et comment les théorèmes d’Euler permettent de le décider, avec un exemple et un contre-exemple.',
      must: ['Parcours eulérien : utiliser chaque arête une seule fois (≠ hamiltonien : chaque sommet une seule fois)', 'Cycle eulérien (eulérien) : parcours fermé ; chaîne eulérienne (semi-eulérien) : non fermé', 'Graphe connexe : cycle eulérien ⇔ tous les degrés pairs', 'Graphe connexe : chaîne eulérienne ⇔ exactement deux sommets de degré impair (les extrémités)', 'Un exemple (K₅, chemin) et un contre-exemple (graphe de la diapo 10, ou deux triangles disjoints)'],
      pitfalls: ['Oublier la connexité', 'Confondre sommets et arêtes (Hamilton vs Euler)', 'Croire que plus de deux sommets impairs permet encore une chaîne'],
      beginner: ['Pourquoi les degrés doivent-ils être pairs pour revenir au départ ?', 'Peut-on dessiner deux triangles séparés sans lever le crayon ?', 'Combien de sommets de degré impair peut-on avoir au plus ?', 'Quelle différence avec visiter chaque sommet une seule fois ?'],
      model: '<p>Un <b>parcours eulérien</b> utilise <b>chaque arête exactement une fois</b> (on peut repasser par un sommet). Si le parcours est fermé, c’est un <b>cycle eulérien</b> (le graphe est eulérien) ; sinon c’est une <b>chaîne eulérienne</b> (semi-eulérien). Pour un graphe <b>connexe</b> : il a un cycle eulérien si et seulement si tous ses sommets sont de degré pair ; il a une chaîne eulérienne si et seulement si exactement deux sommets sont de degré impair (ce sont les extrémités). Exemple : K<sub>5</sub> (tous les degrés valent 4) est eulérien. Contre-exemple : le graphe de la diapo 10 a 4 sommets impairs, donc aucun parcours eulérien ; deux triangles disjoints ont des degrés pairs mais ne sont pas connexes.</p>'
    },
    recap: {
      key: ['Parcours eulérien : chaque arête une seule fois (diapo 23) ; hamiltonien : chaque sommet une seule fois.', 'Eulérien : cycle passant une fois par toutes les arêtes ; semi-eulérien : chaîne passant une fois par toutes les arêtes (diapo 24).', 'Graphe connexe : cycle eulérien ⇔ tous les sommets de degré pair (diapo 24).', 'Graphe connexe : chaîne eulérienne ⇔ exactement deux sommets de degré impair, ses extrémités (diapo 24).', 'Hors cours : le nombre de sommets impairs est pair ; la diapo 25 se modélise par un graphe dont 4 sommets sont impairs : tracé impossible.'],
      defs: [{ t: 'Graphe eulérien', d: 'Graphe admettant un cycle passant une et une seule fois par toutes les arêtes.', slide: '24' }, { t: 'Graphe semi-eulérien', d: 'Graphe admettant une chaîne passant une et une seule fois par toutes les arêtes.', slide: '24' }],
      thms: [{ t: 'Théorème d’Euler (cycle)', s: 'Un graphe connexe G admet un cycle eulérien si et seulement si tous ses sommets sont de degré pair.', cond: 'G connexe (diapo 24)' }, { t: 'Théorème d’Euler (chaîne)', s: 'Un graphe connexe G admet une chaîne eulérienne (d’extrémités u et v) si et seulement si il existe exactement deux sommets de degré impair (u et v).', cond: 'G connexe (diapo 24)' }],
      formulas: [{ t: 'Décision (graphe connexe)', f: '0 impair → cycle ; 2 impairs → chaîne ; ≥ 4 impairs → rien' }]
    },
    qs: [
      qb.choice('n13.q1', 1, 'D’après la diapo 24, un graphe est <b>eulérien</b> s’il est possible de trouver…', ['un cycle passant une et une seule fois par toutes les arêtes', 'un cycle passant une et une seule fois par tous les sommets', 'une chaîne passant une fois par tous les sommets', 'un cycle de longueur 3'], 0, '<p>Eulérien : cycle passant une et une seule fois par toutes les <b>arêtes</b> (diapo 24). Le cycle qui passe une fois par tous les <i>sommets</i> est le cycle hamiltonien (diapo 26).</p>', { src: 'course', slide: '24', tag: 'euler-conditions', hints: ['Eulérien ↔ arêtes ; hamiltonien ↔ sommets (diapo 23).'] }),
      qb.set('n13.q2', 1, 'Donnez l’ensemble des sommets de <b>degré impair</b> de ce graphe.', function (G) { return GR.oddVertices(G); }, function (G) { return '<p>Degrés : ' + degList(G) + '. Sommets de degré impair : ' + oddTxt(G) + '.</p>'; }, { graph: 's10', tag: 'euler-conditions', hints: ['Calculez le degré de chaque sommet.'] }),
      qb.text('n13.q3', 1, 'Expliquez avec vos mots la différence entre un graphe eulérien et un graphe semi-eulérien, et quelle condition sur les degrés correspond à chacun (graphe connexe).', '<p>Un graphe eulérien admet un cycle (parcours fermé) passant une fois par toutes les arêtes ; pour un graphe connexe, c’est équivalent à avoir tous les sommets de degré pair. Un graphe semi-eulérien admet une chaîne (non fermée) passant une fois par toutes les arêtes ; pour un graphe connexe, c’est équivalent à avoir exactement deux sommets de degré impair, qui sont les extrémités de la chaîne.</p>', ['Eulérien : cycle passant une fois par toutes les arêtes', 'Semi-eulérien : chaîne passant une fois par toutes les arêtes', 'Cycle eulérien ⇔ tous les degrés pairs (graphe connexe)', 'Chaîne eulérienne ⇔ exactement deux sommets de degré impair'], { src: 'course', slide: '24', tag: 'euler-conditions', hints: ['Reprenez les deux théorèmes de la diapo 24.'] }),
      qb.choice('n13.q4', 2, 'Ce graphe est connexe. Que peut-on dire de ses parcours eulériens ?', OPTS, kindIdx, function (G) { var e = GR.euler(G); return '<p>Degrés : ' + degList(G) + ' ; sommets de degré impair : ' + oddTxt(G) + '. ' + (e.kind === 'cycle' ? 'Aucun sommet impair : cycle eulérien.' : e.kind === 'chain' ? 'Exactement deux sommets impairs : chaîne eulérienne entre eux, pas de cycle.' : 'Plus de deux sommets impairs : ni cycle ni chaîne eulérienne.') + '</p>'; }, { graph: 'k5', src: 'course', slide: '24', tag: 'euler-conditions', hints: ['Comptez les sommets de degré impair.'] }),
      qb.choice('n13.q5', 2, 'Ce graphe est connexe. Que peut-on dire de ses parcours eulériens ?', OPTS, kindIdx, function (G) { return '<p>Degrés : ' + degList(G) + ' ; sommets de degré impair : ' + oddTxt(G) + '. Il y en a ' + GR.oddVertices(G).length + ' : ni cycle ni chaîne eulérienne.</p>'; }, { graph: 's10', src: 'course', slide: '24', tag: 'euler-conditions', hints: ['Comptez les sommets de degré impair : 0, 2 ou plus ?'] }),
      qb.choice('n13.q6', 2, 'Le cube de la diapo 28 admet-il un cycle ou une chaîne eulérienne ?', OPTS, kindIdx, function (G) { return '<p>Chacun des 8 sommets est de degré 3 (impair) : il y a 8 sommets de degré impair. Le cube n’est ni eulérien ni semi-eulérien, ce que demande de montrer la diapo 28 (avec le fait qu’il est hamiltonien).</p>'; }, { graph: 's28a', src: 'course', slide: '28', tag: 'euler-conditions', hints: ['Quel est le degré de chaque sommet du cube ?'] }),
      qb.tf('n13.q7', 2, 'Un graphe dont tous les sommets sont de degré pair admet toujours un cycle eulérien.', false, ['Il faut aussi que le graphe soit connexe : deux cycles disjoints ont tous leurs degrés pairs mais pas de cycle eulérien.', 'Parce que le nombre de sommets de degré impair est toujours pair.', 'Parce que le graphe doit avoir un nombre impair de sommets.', 'Il faut que tous les degrés soient égaux.'], 0, '<p>Les théorèmes de la diapo 24 portent sur un graphe <b>connexe</b>. Deux triangles disjoints ont tous leurs degrés égaux à 2, mais aucun cycle ne peut utiliser les arêtes des deux.</p>', { graph: TT, src: 'course', slide: '24', tag: 'euler-connexite', hints: ['Relisez les hypothèses du théorème.'] }),
      qb.walk('n13.q8', 2, 'Donnez un <b>cycle eulérien</b> de ce graphe : il passe une et une seule fois par chaque arête et revient à son sommet de départ (sommets séparés par des tirets).', function (g, seq) {
        var cw = GR.classifyWalk(g, seq);
        if (!cw.valid) return { ok: false, msg: cw.reason };
        if (!GR.isEulerTrail(g, seq)) { var used = seq.length - 1; return { ok: false, msg: used < GR.m(g) ? 'Il reste des arêtes non utilisées : ce parcours en utilise ' + used + ' sur ' + GR.m(g) + '.' : 'Ce parcours n’est pas eulérien : une arête est répétée.' }; }
        if (!cw.closed) return { ok: false, msg: 'Toutes les arêtes sont utilisées, mais le parcours n’est pas fermé : un cycle revient au départ.' };
        return { ok: true };
      }, '<p>Degrés 2, 2, 4, 2, 2 : tous pairs, graphe connexe, donc cycle eulérien. Par exemple C–A–B–C–D–E–C : on parcourt le premier triangle, puis le second.</p>', { graph: BOW, sample: 'C-A-B-C-D-E-C', tag: 'euler-construire', hints: ['Partez du sommet de degré 4.', 'Parcourez un triangle, revenez au sommet commun, puis parcourez l’autre.'] }),
      qb.num('n13.q9', 3, 'Combien de sommets de degré impair le graphe (modèle de la diapo 25 : régions = sommets, segments = arêtes) possède-t-il ?', function (G) { return GR.oddVertices(G).length; }, function (G) { return '<p>Degrés : ' + degList(G) + '. Sommets de degré impair : ' + oddTxt(G) + ', soit ' + GR.oddVertices(G).length + '.</p>'; }, { graph: 's25dual', src: 'extra', tag: 'euler-conditions', hints: ['Calculez le degré de chaque sommet : l’extérieur X est relié à 9 segments.'] }),
      qb.choice('n13.q10', 3, '<b>Question de la diapo 25</b> : peut-on tracer une courbe, sans lever le crayon, qui coupe chacun des 16 segments de la figure exactement une fois ? (Modèle : régions = sommets, segments = arêtes entre les deux régions qu’ils séparent.)', ['Non : le modèle a 4 sommets de degré impair', 'Oui : tous les degrés du modèle sont pairs', 'Oui : le modèle a exactement 2 sommets de degré impair', 'On ne peut pas le savoir avec ce cours'], 0, '<p>La courbe traverse chaque segment une fois : c’est une chaîne eulérienne du graphe dont les sommets sont les régions. Degrés : extérieur 9, trois pièces de degré 5, deux de degré 4. Quatre sommets impairs : pas de chaîne eulérienne, donc le tracé est impossible. (La diapo ne donne pas la réponse ni le modèle.)</p>', { graph: 's25dual', transfer: true, src: 'extra', tag: 'euler-conditions', hints: ['Une courbe qui coupe chaque segment une fois revient à passer par chaque arête du graphe des régions une fois.', 'Comptez les sommets de degré impair.'] }),
      qb.edges('n13.q11', 3, 'Écrivez la liste des arêtes d’un graphe simple non orienté <b>connexe</b> sur les cinq sommets A, B, C, D, E qui admet une <b>chaîne eulérienne mais pas de cycle eulérien</b>.', function (g) {
        var vs = ['A', 'B', 'C', 'D', 'E'];
        if (!hasAll(g, vs)) return { ok: false, msg: 'Le graphe doit avoir exactement les cinq sommets A à E.' };
        if (!GR.isSimple(g)) return { ok: false, msg: 'Le graphe doit être simple (ni boucle, ni arête répétée).' };
        if (!GR.isConnected(g)) return { ok: false, msg: 'Le graphe n’est pas connexe.' };
        var o = GR.oddVertices(g);
        if (o.length !== 2) return { ok: false, msg: 'Votre graphe a ' + o.length + ' sommet(s) de degré impair (' + (o.length ? U.set(o) : 'aucun') + ') ; il doit en avoir exactement 2.' };
        return { ok: true };
      }, '<p>Il faut un graphe connexe avec exactement deux sommets de degré impair. Le chemin A–B–C–D–E convient : degrés 1, 2, 2, 2, 1, donc chaîne eulérienne A–B–C–D–E.</p>', { sample: 'A-B, B-C, C-D, D-E', challenge: true, tag: 'euler-conditions', hints: ['Il faut exactement deux sommets de degré impair.', 'Le graphe doit être connexe : pensez à un chemin.'] })
    ]
  });
  })();
  /* ================= n14 ================= */
  (function () {
    function Wk(seq) { return { walk: { seq: seq, numbers: true } }; }
    var C5 = mk('ABCDE', ['AB', 'BC', 'CD', 'DE', 'EA']), BOW = mk('ABCDE', ['AB', 'BC', 'CA', 'CD', 'DE', 'EC']), K5 = GS.get('k5');
    var CUBE_CYC = ['a', 'e', 'f', 'g', 'h', 'd', 'c', 'b', 'a'];
    var OPTS_H = ['Il admet un cycle hamiltonien', 'Il admet une chaîne hamiltonienne mais pas de cycle hamiltonien', 'Il n’admet ni cycle ni chaîne hamiltonienne'];
    var OPTS_E = ['Il admet un cycle eulérien', 'Il admet une chaîne eulérienne (non fermée) mais pas de cycle eulérien', 'Il n’admet ni cycle eulérien ni chaîne eulérienne'];
    function hIdx(G) { var h = GR.hamilton(G); return h.cycle ? 0 : h.path ? 1 : 2; }
    function eIdx(G) { var e = GR.euler(G); return e.kind === 'cycle' ? 0 : e.kind === 'chain' ? 1 : 2; }
    function oddTxt(G) { var o = GR.oddVertices(G); return o.length ? U.set(o) : 'aucun'; }
  GF.content.add({
    id: 'n14', title: 'Parcours hamiltoniens', short: 'Parcours hamiltoniens', slides: '26–28', prereqs: ['n13', 'n10'],
    objectives: [
      'Définir graphe hamiltonien (cycle passant une fois par tous les sommets) et semi-hamiltonien (chaîne).',
      'Savoir qu’un sommet de degré 1 empêche un cycle hamiltonien, que K<sub>n</sub> est hamiltonien pour n ≥ 3 et que les degrés seuls ne donnent pas de critère simple.',
      'Appliquer le théorème et le corollaire de la diapo 27 (conditions suffisantes sur les degrés) sans les prendre pour des conditions nécessaires.',
      'Montrer qu’un graphe est hamiltonien (en exhibant un cycle) et non eulérien (en comptant les degrés impairs), comme à la diapo 28.'
    ],
    course: [
      { k: 'def', slide: '26', t: 'Graphe hamiltonien', h: '<p>On dit qu’un graphe est <b>hamiltonien</b> s’il est possible de trouver un <b>cycle</b> passant une et une seule fois par <b>tous les sommets</b>.</p>', g: 's28a', go: { walk: { seq: CUBE_CYC, numbers: true } } },
      { k: 'def', slide: '26', t: 'Graphe semi-hamiltonien', h: '<p>On dit qu’un graphe est <b>semi-hamiltonien</b> s’il est possible de trouver une <b>chaîne</b> passant une et une seule fois par tous les sommets.</p>' },
      { k: 'rem', slide: '26', t: 'Sommet de degré 1', h: '<p>Un sommet de <b>degré 1</b> empêche un cycle hamiltonien.</p>', g: 's10', go: { showDeg: true, hlV: { F: 'hl' } } },
      { k: 'rem', slide: '26', t: 'Graphe complet', h: '<p><b>K<sub>n</sub></b> est hamiltonien pour <b>n ≥ 3</b>.</p>', g: 'k5' },
      { k: 'rem', slide: '26', t: 'Pas de critère aussi simple que pour Euler', h: '<p>Les degrés seuls ne donnent pas un critère aussi simple que pour Euler (diapo 24).</p>' },
      { k: 'q', slide: '26', t: 'Question du cours', h: '<p>« Un cycle peut-il être hamiltonien sans utiliser toutes les arêtes du graphe ? » La diapo ne donne pas la réponse : voir la résolution hors diapo.</p>' },
      { k: 'thm', slide: '27', t: 'Théorème (conditions sur les degrés)', h: '<p>Soit <i>G = (V, E)</i> un graphe <b>simple</b> d’ordre <i>n ≥ 3</i>. Si pour toute paire (<i>u, v</i>) de sommets <b>non adjacents</b>, on a <span class="mth">d(u) + d(v) ≥ n</span>, alors <i>G</i> est hamiltonien.</p>' },
      { k: 'thm', slide: '27', t: 'Corollaire', h: '<p>Soit <i>G = (V, E)</i> un graphe <b>simple</b> d’ordre <i>n ≥ 3</i>. Si pour tout sommet <i>u</i> de <i>G</i>, on a <span class="mth">d(u) ≥ n/2</span>, alors <i>G</i> est hamiltonien.</p>' },
      { k: 'q', slide: '28', t: 'Application : deux graphes à étudier', h: '<p>« Montrer que ces deux graphes sont hamiltoniens et non eulériens. » Les deux figures sont un « cube » (8 sommets, 12 arêtes) et une « échelle » à 8 sommets avec deux diagonales (12 arêtes). La diapo ne donne pas la correction : voir ci-dessous.</p>', g: 's28a' },
      { k: 'warn', slide: '27', t: 'Théorème et corollaire non nommés', h: '<p>Le théorème et son corollaire sont donnés sans nom. <b>Hors cours :</b> la littérature les désigne par <b>Ore</b> (théorème) et <b>Dirac</b> (corollaire). Ce sont des conditions <b>suffisantes</b>, non nécessaires : si elles ne sont pas remplies, on ne peut rien conclure.</p>' },
      { k: 'warn', slide: '26', t: 'Questions et applications sans correction', h: '<p>La question de la diapo 26 et l’application de la diapo 28 n’ont pas de correction dans le PDF. Les deux graphes de la diapo 28 sont lus sur la figure : un cube (8 sommets, 12 arêtes, 3-régulier) et une « échelle » à 8 sommets avec deux diagonales (12 arêtes, degrés 2, 4, 3, 3, 3, 3, 4, 2). Une lecture différente de la figure changerait les degrés indiqués.</p>', g: 's28b' },
      { k: 'extra', t: 'Réponse à la question de la diapo 26 (hors diapo)', h: '<p><b>Oui.</b> Un cycle hamiltonien d’un graphe à <i>n</i> sommets utilise exactement <i>n</i> arêtes. Si le graphe en a davantage, certaines ne servent pas. Exemple : le cube a 8 sommets et 12 arêtes ; le cycle a–e–f–g–h–d–c–b–a n’en utilise que 8.</p>', g: 's28a', go: { walk: { seq: CUBE_CYC, numbers: true } } },
      { k: 'extra', t: 'Pourquoi un sommet de degré 1 bloque (hors diapo)', h: '<p>Dans un cycle, chaque sommet est atteint par une arête et quitté par une autre : il faut donc <b>au moins deux arêtes</b> en chaque sommet. Un sommet de degré 1 ne peut pas appartenir à un cycle. Le graphe de la diapo 10 (sommet F de degré 1) n’a pas de cycle hamiltonien ; il a une chaîne hamiltonienne F–E–D–B–C–A, donc il est semi-hamiltonien.</p>', g: 's10', go: { walk: { seq: ['F', 'E', 'D', 'B', 'C', 'A'], numbers: true } } },
      { k: 'extra', t: 'Condition suffisante, pas nécessaire (hors diapo)', h: '<p>Le cycle à 5 sommets est hamiltonien (c’est lui-même un cycle qui passe par tous les sommets) ; pourtant chaque sommet est de degré 2, et pour deux sommets non adjacents d(u) + d(v) = 4 < 5 = n : les conditions de la diapo 27 ne sont pas remplies. De même le cube (diapo 28) est hamiltonien alors que d(u) + d(v) = 6 < 8 pour deux sommets non adjacents : le théorème ne permet pas de conclure, il faut exhiber un cycle.</p>', g: C5, go: { showDeg: true } },
      { k: 'extra', t: 'Solution de la diapo 28 (hors diapo)', h: '<p><b>Cube</b> : cycle hamiltonien a–e–f–g–h–d–c–b–a (8 arêtes) ; les 8 sommets sont de degré 3 (impair) : il y a 8 sommets impairs, donc ni cycle ni chaîne eulérienne. <b>Échelle</b> : le même cycle a–e–f–g–h–d–c–b–a est valide ; degrés 2, 4, 3, 3, 3, 3, 4, 2 : les sommets c, d, e, f sont de degré impair (4 sommets), donc le graphe n’est pas eulérien.</p>', g: 's28b', go: { showDeg: true, walk: { seq: CUBE_CYC, numbers: true } } },
      { k: 'extra', t: 'Euler et Hamilton sont indépendants (hors diapo)', h: '<p>Le nœud papillon (deux triangles qui se touchent en un sommet) est eulérien (tous les degrés sont pairs : 2, 2, 4, 2, 2) mais <b>pas hamiltonien</b> : un cycle passant par les 5 sommets devrait traverser le sommet commun deux fois. À l’inverse, le cube est hamiltonien mais pas eulérien.</p>', g: BOW, go: { showDeg: true } }
    ],
    guided: [
      { h: '<p>Le graphe de la diapo 10 a un sommet de degré 1 : F.</p>', g: 's10', go: { showDeg: true, hlV: { F: 'hl' } }, ask: 'Ce graphe a-t-il un cycle hamiltonien ? A-t-il une chaîne hamiltonienne ?', reveal: '<p>Pas de cycle hamiltonien : F, de degré 1, ne peut pas être traversé par un cycle (il faut deux arêtes). Mais il y a une chaîne hamiltonienne F–E–D–B–C–A, qui passe une fois par les six sommets : le graphe est <b>semi-hamiltonien</b>.</p>' },
      { h: '<p>K<sub>5</sub> est complet : tous les sommets sont deux à deux adjacents (diapo 26 : K<sub>n</sub> est hamiltonien pour n ≥ 3).</p>', g: 'k5', ask: 'Donnez un cycle hamiltonien de K₅.', reveal: '<p>1–2–3–4–5–1 passe une fois par chaque sommet. (Toute permutation des sommets suivie d’un retour au départ convient, puisque toutes les paires sont adjacentes.)</p>' },
      { h: '<p>Appliquons le théorème de la diapo 27 au cycle à 5 sommets (n = 5, tous les degrés valent 2).</p>', g: C5, go: { showDeg: true }, ask: 'Les conditions du théorème sont-elles remplies ? Le graphe est-il hamiltonien ?', reveal: '<p>Pour deux sommets non adjacents, d(u) + d(v) = 4 < 5 : les conditions ne sont pas remplies. Pourtant le graphe est hamiltonien (c’est un cycle qui passe par tous les sommets). Les conditions sont <b>suffisantes</b>, pas nécessaires.</p>' },
      { h: '<p>Voici le cube de la diapo 28, avec 12 arêtes.</p>', g: 's28a', go: { walk: { seq: CUBE_CYC, numbers: true } }, ask: 'Combien d’arêtes utilise le cycle hamiltonien tracé ? Répond-il à la question de la diapo 26 ?', reveal: '<p>Un cycle hamiltonien à 8 sommets utilise 8 arêtes ; le cube en a 12. Donc <b>oui</b>, un cycle peut être hamiltonien sans utiliser toutes les arêtes.</p>' },
      { h: '<p>La diapo 28 demande de montrer deux choses sur le cube : hamiltonien et non eulérien.</p>', g: 's28a', go: { showDeg: true }, ask: 'Comment montrer qu’il n’est pas eulérien ?', reveal: '<p>Les 8 sommets sont de degré 3 (impair) : il y a plus de deux sommets de degré impair, donc il n’y a ni cycle ni chaîne eulérienne (diapo 24).</p>' }
    ],
    examples: [
      { t: 'K₅ : hamiltonien', h: '<p>Le cycle 1–2–3–4–5–1 passe une fois par chaque sommet.</p>', g: 'k5', go: Wk(['1', '2', '3', '4', '5', '1']) },
      { t: 'Le cube (diapo 28) : hamiltonien, non eulérien', h: '<p>Cycle hamiltonien a–e–f–g–h–d–c–b–a ; tous les degrés valent 3 (impair).</p>', g: 's28a', go: { showDeg: true, walk: { seq: CUBE_CYC, numbers: true } } },
      { t: 'L’échelle (diapo 28) : hamiltonienne, non eulérienne', h: '<p>Le même cycle a–e–f–g–h–d–c–b–a est valide ; quatre sommets de degré impair (c, d, e, f).</p>', g: 's28b', go: { showDeg: true, walk: { seq: CUBE_CYC, numbers: true } } },
      { t: 'Le cycle à 5 sommets : hamiltonien sans vérifier le théorème', h: '<p>Les conditions de la diapo 27 ne sont pas remplies, mais le graphe est hamiltonien : le théorème n’est pas une condition nécessaire.</p>', g: C5, go: { showDeg: true } },
      { t: 'Contre-exemple : le graphe de la diapo 10 n’a pas de cycle hamiltonien', h: '<p>Le sommet F est de degré 1 : aucun cycle ne passe par F.</p>', g: 's10', go: { showDeg: true, hlV: { F: 'hl' } }, counter: true },
      { t: 'Contre-exemple : eulérien mais pas hamiltonien', h: '<p>Nœud papillon : degrés 2, 2, 4, 2, 2 (tous pairs), connexe, donc eulérien ; mais aucun cycle ne passe une seule fois par les 5 sommets.</p>', g: BOW, go: { showDeg: true }, counter: true }
    ],
    compare: [{ t: 'Euler et Hamilton', cols: ['', 'Parcours eulérien', 'Parcours hamiltonien'], rows: [['Ce qu’on utilise une seule fois', 'chaque arête (diapo 23)', 'chaque sommet (diapo 23)'], ['Critère sur les degrés', 'oui : 0 ou 2 sommets de degré impair (graphe connexe)', 'non : seulement des conditions suffisantes (diapo 27)'], ['Cube (diapo 28)', 'non (8 sommets impairs)', 'oui'], ['Nœud papillon', 'oui (degrés tous pairs)', 'non'], ['K₅', 'oui (degrés 4)', 'oui']] }],
    mistakes: [
      { tag: 'hamilton-conditions', wrong: 'Un parcours hamiltonien passe une seule fois par chaque arête.', right: 'C’est le parcours <b>eulérien</b>. Le parcours hamiltonien passe une seule fois par chaque <b>sommet</b> (diapo 23).' },
      { tag: 'hamilton-conditions', wrong: 'Si d(u) + d(v) < n pour deux sommets non adjacents, le graphe n’est pas hamiltonien.', right: 'Le théorème est une condition <b>suffisante</b> : le cycle à 5 sommets est hamiltonien alors que d(u) + d(v) = 4 < 5.' },
      { tag: 'hamilton-conditions', wrong: 'Un cycle hamiltonien doit utiliser toutes les arêtes du graphe.', right: 'Il utilise exactement n arêtes pour n sommets : le cube a 12 arêtes et un cycle hamiltonien n’en utilise que 8.' },
      { tag: 'hamilton-conditions', wrong: 'Un graphe dont tous les degrés sont pairs est hamiltonien.', right: 'Le nœud papillon a tous ses degrés pairs et n’est pas hamiltonien. Les degrés seuls ne donnent pas de critère simple (diapo 26).' },
      { tag: 'hamilton-conditions', wrong: 'Un sommet de degré 1 ne gêne pas un cycle hamiltonien.', right: 'Un cycle exige au moins deux arêtes en chaque sommet : un sommet de degré 1 empêche tout cycle hamiltonien (diapo 26).' }
    ],
    alt: [
      '<p>Euler : un facteur doit passer dans <b>chaque rue</b> une seule fois. Hamilton : un voyageur doit visiter <b>chaque ville</b> une seule fois et revenir chez lui. Les deux questions semblent voisines, mais pour Hamilton il n’existe pas de test simple sur les degrés.</p>',
      '<p>Pour montrer qu’un graphe est hamiltonien, <b>exhibez un cycle</b> : citez la suite de sommets et vérifiez que chaque paire consécutive est une arête et que chaque sommet apparaît une fois. Pour montrer qu’il ne l’est pas, cherchez un obstacle (sommet de degré 1…) ou une raison propre au graphe.</p>',
      '<p>Pour les conditions de la diapo 27 : calculez les degrés ; si tous valent au moins n/2, c’est gagné (corollaire). Sinon, regardez uniquement les paires non adjacentes : si pour chacune d(u) + d(v) ≥ n, c’est gagné aussi. Si aucune condition ne marche, on ne peut pas conclure avec ce théorème.</p>'
    ],
    socratic: {
      warm: { id: 'n14.s0', type: 'choice', q: 'Un parcours hamiltonien passe une et une seule fois par chaque…', options: ['sommet', 'arête', 'composante connexe', 'sommet de degré impair'], answer: 0,
        counter: '<p>Cas plus simple : dans un triangle A–B–C, le trajet A–B–C–A passe par chaque sommet une seule fois. Est-ce le même type de parcours que celui d’Euler ?</p>', hints: ['<p>Relisez la diapo 23 : « Visiter chaque site » ↔ hamiltonien.</p>', '<p>Eulérien ↔ arêtes ; hamiltonien ↔ sommets.</p>'],
        ok: '<p>Exact. Un sommet de degré 1 peut-il appartenir à un cycle ?</p>', explain: '<p>Parcours hamiltonien : chaque <i>sommet</i> une seule fois (diapo 23). Parcours eulérien : chaque <i>arête</i> une seule fois. Exemple : dans K<sub>4</sub>, le cycle 1–2–3–4–1 est hamiltonien mais n’utilise que 4 des 6 arêtes.</p>', restate: '<p>Redites la différence entre eulérien et hamiltonien.</p>' },
      steps: [
        { id: 'n14.s1', type: 'choice', g: 's10', go: { showDeg: true }, q: 'Le graphe de la diapo 10 a un sommet de degré 1 (F). Admet-il un cycle hamiltonien ?', options: ['Oui : il est connexe', 'Non : un sommet de degré 1 empêche un cycle hamiltonien', 'Oui : il a un nombre pair de sommets', 'Non : il a des sommets de degré impair'], answer: 1,
          counter: '<p>Cas plus simple : dans un cycle, combien d’arêtes touchent chaque sommet ?</p>', hints: ['<p>Relisez la diapo 26 : « Un sommet de degré 1 empêche… ».</p>', '<p>Un cycle entre dans un sommet par une arête et en sort par une autre.</p>'],
          ok: '<p>Oui. Existe-t-il quand même une chaîne qui passe une fois par tous les sommets ?</p>', explain: '<p>Dans un cycle, chaque sommet a deux arêtes (une pour entrer, une pour sortir) ; un sommet de degré 1 n’en a qu’une, donc il ne peut pas être dans un cycle hamiltonien. Exemple : le chemin A–B–C ne contient aucun cycle.</p>', restate: '<p>Expliquez pourquoi un sommet de degré 1 bloque tout cycle.</p>' },
        { id: 'n14.s2', type: 'num', g: 's28a', q: 'Combien d’arêtes utilise un cycle hamiltonien du <b>cube</b> de la diapo 28 (8 sommets, 12 arêtes) ?', answer: 8,
          counter: '<p>Cas plus simple : un cycle hamiltonien d’un carré (4 sommets) utilise combien d’arêtes ?</p>', hints: ['<p>Un cycle qui passe une fois par chaque sommet a autant d’arêtes que de sommets.</p>', '<p>Comptez : chaque sommet est relié au suivant, puis le dernier revient au premier.</p>'],
          ok: '<p>Oui, 8 sur 12. Cela répond-il à la question de la diapo 26 ?</p>', explain: '<p>Un cycle passant une fois par les 8 sommets utilise 8 arêtes ; le cube en a 12, donc 4 ne servent pas. Exemple : le carré est son propre cycle hamiltonien (4 arêtes).</p>', restate: '<p>Répondez à la question de la diapo 26 avec vos mots.</p>' },
        { id: 'n14.s3', type: 'choice', g: C5, go: { showDeg: true }, q: 'Le cycle à 5 sommets est hamiltonien, mais d(u) + d(v) = 4 < 5 pour deux sommets non adjacents. Que conclure sur le théorème de la diapo 27 ?', options: ['Il est faux', 'Ses conditions sont suffisantes mais pas nécessaires', 'Il ne s’applique qu’aux graphes complets', 'Ses conditions sont nécessaires'], answer: 1,
          counter: '<p>Cas plus simple : « s’il pleut, la rue est mouillée » : si la rue est mouillée, peut-on conclure qu’il pleut ?</p>', hints: ['<p>Le théorème dit « si… alors G est hamiltonien ». A-t-on le droit de renverser l’implication ?</p>', '<p>Ici le graphe est hamiltonien sans que la condition soit vérifiée.</p>'],
          ok: '<p>Oui. Que peut-on conclure si la condition est remplie ?</p>', explain: '<p>Le théorème énonce une implication (condition ⇒ hamiltonien) : il suffit que la condition soit remplie pour conclure, mais elle n’est pas nécessaire. Exemple : le cycle à 5 sommets est hamiltonien sans la remplir.</p>', restate: '<p>Redites la différence entre condition suffisante et condition nécessaire.</p>' },
        { id: 'n14.s4', type: 'num', q: 'D’après le corollaire de la diapo 27, un graphe simple à <b>8 sommets</b> est hamiltonien si tous ses sommets ont un degré au moins égal à… (donnez ce minimum).', answer: 4,
          counter: '<p>Cas plus simple : pour n = 4, le corollaire demande d(u) ≥ 2 : le carré le vérifie-t-il ?</p>', hints: ['<p>Le corollaire demande d(u) ≥ n/2.</p>', '<p>Calculez 8 / 2.</p>'],
          ok: '<p>Oui, 4. Et pour n = 7, quel serait le plus petit degré entier qui convient ?</p>', explain: '<p>Corollaire : d(u) ≥ n/2. Pour n = 8 : d(u) ≥ 4. Exemple : pour n = 4, il faut d(u) ≥ 2, ce que satisfait le carré (tous les degrés valent 2).</p>', restate: '<p>Redites le corollaire avec vos mots.</p>' },
        { id: 'n14.s5', type: 'text', q: 'Expliquez avec vos mots la différence entre un parcours eulérien et un parcours hamiltonien, et ce que l’on sait des critères pour chacun.', expect: ['Eulérien : chaque arête une seule fois ; hamiltonien : chaque sommet une seule fois', 'Eulérien : critère simple sur les degrés (0 ou 2 sommets impairs, graphe connexe)', 'Hamiltonien : pas de critère aussi simple, seulement des conditions suffisantes (diapo 27)'],
          counter: '<p>Appliquez les deux notions au cube (diapo 28) : qu’obtenez-vous ?</p>', hints: ['<p>Une notion concerne les arêtes, l’autre les sommets.</p>', '<p>Le cube est hamiltonien mais pas eulérien.</p>'],
          ok: '<p>Bien. Citez un graphe eulérien qui n’est pas hamiltonien.</p>', explain: '<p>Eulérien : chaque arête une fois, avec un critère simple sur les degrés. Hamiltonien : chaque sommet une fois, sans critère simple, seulement des conditions suffisantes (théorème et corollaire de la diapo 27). Exemple : le cube est hamiltonien mais n’est pas eulérien (8 sommets de degré impair).</p>', restate: '<p>Reformulez : pourquoi les deux notions sont-elles indépendantes ?</p>' }
      ],
      verify: { gen: 'hamilton', level: 2 }
    },
    feynman: {
      topic: 'Parcours hamiltoniens',
      prompt: 'Expliquez à un débutant ce qu’est un graphe hamiltonien, ce que dit le théorème de la diapo 27 et en quoi c’est différent d’un graphe eulérien, avec un exemple et un contre-exemple.',
      must: ['Hamiltonien : cycle passant une seule fois par chaque sommet ; semi-hamiltonien : chaîne', 'Un sommet de degré 1 empêche un cycle hamiltonien ; K_n est hamiltonien pour n ≥ 3', 'Théorème/corollaire : conditions suffisantes sur les degrés (d(u) + d(v) ≥ n ; d(u) ≥ n/2), pas nécessaires', 'Différence avec Euler : sommets vs arêtes, pas de critère simple', 'Un exemple (cube, K₅) et un contre-exemple (graphe de la diapo 10, nœud papillon)'],
      pitfalls: ['Confondre sommets et arêtes (Euler vs Hamilton)', 'Prendre une condition suffisante pour une condition nécessaire', 'Croire qu’un cycle hamiltonien utilise toutes les arêtes'],
      beginner: ['Pourquoi un sommet de degré 1 pose-t-il problème ?', 'Si le théorème ne s’applique pas, le graphe n’est-il pas hamiltonien ?', 'Un cycle hamiltonien utilise-t-il toutes les arêtes ?', 'Y a-t-il une formule simple comme pour Euler ?'],
      model: '<p>Un graphe est <b>hamiltonien</b> s’il possède un cycle qui passe <b>une seule fois par chaque sommet</b> ; <b>semi-hamiltonien</b> s’il possède une chaîne qui le fait. Contrairement à Euler (qui compte les arêtes et se décide sur les degrés), il n’y a pas de critère simple : un sommet de degré 1 empêche un cycle, K<sub>n</sub> est hamiltonien pour n ≥ 3, et le théorème de la diapo 27 (d(u) + d(v) ≥ n pour toute paire non adjacente, ou d(u) ≥ n/2 pour tout u) donne seulement une <b>condition suffisante</b>. Exemple : le cube est hamiltonien (cycle a–e–f–g–h–d–c–b–a) mais pas eulérien. Contre-exemple : le graphe de la diapo 10 n’a pas de cycle hamiltonien, à cause du sommet F de degré 1.</p>'
    },
    recap: {
      key: ['Hamiltonien : cycle passant une seule fois par tous les sommets ; semi-hamiltonien : chaîne (diapo 26).', 'Un sommet de degré 1 empêche un cycle hamiltonien ; K<sub>n</sub> est hamiltonien pour n ≥ 3 (diapo 26).', 'Théorème (diapo 27) : graphe simple d’ordre n ≥ 3, d(u) + d(v) ≥ n pour toute paire non adjacente ⇒ hamiltonien.', 'Corollaire (diapo 27) : d(u) ≥ n/2 pour tout sommet ⇒ hamiltonien. Ce sont des conditions suffisantes, non nécessaires.', 'Diapo 28 : cube et échelle sont hamiltoniens (on exhibe un cycle) et non eulériens (sommets de degré impair).'],
      defs: [{ t: 'Graphe hamiltonien', d: 'Graphe admettant un cycle passant une et une seule fois par tous les sommets.', slide: '26' }, { t: 'Graphe semi-hamiltonien', d: 'Graphe admettant une chaîne passant une et une seule fois par tous les sommets.', slide: '26' }],
      thms: [{ t: 'Théorème (diapo 27)', s: 'Si pour toute paire (u, v) de sommets non adjacents, d(u) + d(v) ≥ n, alors G est hamiltonien.', cond: 'graphe simple d’ordre n ≥ 3' }, { t: 'Corollaire (diapo 27)', s: 'Si d(u) ≥ n/2 pour tout sommet u, alors G est hamiltonien.', cond: 'graphe simple d’ordre n ≥ 3' }],
      formulas: [{ t: 'Condition sur les paires non adjacentes', f: 'd(u) + d(v) ≥ n' }, { t: 'Condition sur chaque sommet', f: 'd(u) ≥ n / 2' }]
    },
    qs: [
      qb.choice('n14.q1', 1, 'D’après la diapo 26, un graphe est <b>hamiltonien</b> s’il est possible de trouver…', ['un cycle passant une et une seule fois par tous les sommets', 'un cycle passant une et une seule fois par toutes les arêtes', 'une chaîne passant une fois par toutes les arêtes', 'un sommet de degré maximum'], 0, '<p>Hamiltonien : cycle passant une seule fois par tous les <b>sommets</b> (diapo 26). Celui qui passe une fois par toutes les arêtes est le cycle eulérien (diapo 24).</p>', { src: 'course', slide: '26', tag: 'hamilton-conditions', hints: ['Hamiltonien ↔ sommets (diapo 23).'] }),
      qb.choice('n14.q2', 1, 'D’après la diapo 26, le graphe complet K<sub>n</sub> est hamiltonien pour…', ['n ≥ 3', 'n pair seulement', 'tout n ≥ 1', 'n ≥ 10'], 0, '<p>K<sub>n</sub> est hamiltonien pour n ≥ 3 (diapo 26) : toutes les paires de sommets sont adjacentes, on peut les parcourir dans n’importe quel ordre et revenir au départ.</p>', { src: 'course', slide: '26', tag: 'hamilton-conditions', hints: ['Un cycle demande au moins 3 sommets.'] }),
      qb.text('n14.q3', 1, 'Expliquez avec vos mots la différence entre un graphe eulérien et un graphe hamiltonien.', '<p>Un graphe eulérien possède un cycle qui passe une seule fois par chaque <i>arête</i> ; un graphe hamiltonien possède un cycle qui passe une seule fois par chaque <i>sommet</i>. Pour Euler, un critère simple existe sur les degrés (graphe connexe : tous pairs pour un cycle) ; pour Hamilton, il n’y a pas de critère aussi simple.</p>', ['Eulérien : une fois par chaque arête', 'Hamiltonien : une fois par chaque sommet', 'Euler : critère simple sur les degrés', 'Hamilton : pas de critère aussi simple (seulement des conditions suffisantes)'], { src: 'course', slide: '26', tag: 'hamilton-conditions', hints: ['Reprenez la diapo 23 et la dernière puce de la diapo 26.'] }),
      qb.tf('n14.q4', 2, 'Un graphe qui possède un sommet de degré 1 ne peut pas avoir de cycle hamiltonien.', true, ['Dans un cycle, chaque sommet est touché par au moins deux arêtes ; un sommet de degré 1 n’en a qu’une.', 'Parce qu’un sommet de degré 1 est toujours isolé.', 'Parce que le graphe n’est pas connexe.', 'Parce que le nombre de sommets est impair.'], 0, '<p>Un cycle hamiltonien entre dans chaque sommet par une arête et en sort par une autre : il faut au moins deux arêtes par sommet. Un sommet de degré 1 l’empêche (diapo 26).</p>', { src: 'course', slide: '26', tag: 'hamilton-conditions', hints: ['Combien d’arêtes touchent chaque sommet d’un cycle ?'] }),
      qb.choice('n14.q5', 2, 'Ce graphe (diapo 10) admet…', OPTS_H, hIdx, function (G) { var h = GR.hamilton(G); return '<p>F est de degré 1 : pas de cycle hamiltonien. ' + (h.path ? 'La chaîne ' + h.path.join('–') + ' passe une fois par chaque sommet : le graphe est semi-hamiltonien.' : '') + '</p>'; }, { graph: 's10', tag: 'hamilton-conditions', hints: ['Cherchez d’abord un sommet de degré 1.', 'Puis cherchez une chaîne qui passe par tous les sommets, en commençant par F.'] }),
      qb.num('n14.q6', 2, 'Combien d’arêtes utilise un cycle hamiltonien de ce graphe (le cube de la diapo 28) ?', 8, '<p>Un cycle passant une fois par les 8 sommets a 8 arêtes (une par « pas »). Le cube en a 12 : 4 arêtes ne sont pas utilisées.</p>', { graph: 's28a', src: 'extra', tag: 'hamilton-conditions', hints: ['Combien de sommets ? Un cycle a autant d’arêtes que de sommets.'] }),
      qb.walk('n14.q7', 2, 'Donnez un <b>cycle hamiltonien</b> du cube (diapo 28) : un cycle qui passe une et une seule fois par chacun des 8 sommets (répétez le sommet de départ à la fin).', function (g, seq) {
        var cw = GR.classifyWalk(g, seq);
        if (!cw.valid) return { ok: false, msg: cw.reason };
        if (!cw.closed) return { ok: false, msg: 'Un cycle est fermé : il revient à son sommet de départ.' };
        if (!cw.elementaryCycle) return { ok: false, msg: 'Un sommet est répété ou une arête est utilisée deux fois : ce n’est pas un cycle élémentaire.' };
        if (cw.length !== GR.n(g)) return { ok: false, msg: 'Ce cycle passe par ' + cw.length + ' sommet(s) sur ' + GR.n(g) + ' : il doit passer par tous.' };
        return { ok: true };
      }, '<p>Par exemple a–e–f–g–h–d–c–b–a : chaque paire consécutive est une arête, les 8 sommets apparaissent une fois, et on revient en a.</p>', { graph: 's28a', sample: 'a-e-f-g-h-d-c-b-a', src: 'course', slide: '28', tag: 'hamilton-conditions', hints: ['Partez du carré intérieur, passez au carré extérieur par une arête, parcourez-le, puis revenez.', 'Vérifiez chaque paire consécutive.'] }),
      qb.choice('n14.q8', 2, 'Ce graphe (seconde figure de la diapo 28) admet…', OPTS_E, eIdx, function (G) { return '<p>Degrés : ' + degList(G) + ' ; sommets de degré impair : ' + oddTxt(G) + ' (' + GR.oddVertices(G).length + '). Plus de deux sommets impairs : ni cycle ni chaîne eulérienne (diapo 24).</p>'; }, { graph: 's28b', src: 'course', slide: '28', tag: 'hamilton-conditions', hints: ['Comptez les sommets de degré impair.'] }),
      qb.choice('n14.q9', 2, 'Un graphe simple à 7 sommets a tous ses sommets de degré au moins 4. Que peut-on dire ?', ['Il est hamiltonien (corollaire de la diapo 27 : d(u) ≥ n/2 = 3,5)', 'Il n’est pas hamiltonien', 'Il est eulérien', 'On ne peut rien dire sans voir le graphe'], 0, '<p>n = 7, donc n/2 = 3,5. Tous les degrés sont ≥ 4 ≥ 3,5 : le corollaire (graphe simple, n ≥ 3) permet de conclure que G est hamiltonien. On ne peut rien en déduire sur Euler (les degrés peuvent être impairs).</p>', { src: 'course', slide: '27', tag: 'hamilton-conditions', hints: ['Calculez n/2 puis comparez à 4.'] }),
      qb.tf('n14.q10', 3, 'Si, pour deux sommets non adjacents u et v, on a d(u) + d(v) &lt; n, alors le graphe n’est pas hamiltonien.', false, ['Le théorème donne une condition suffisante, pas nécessaire : le cycle à 5 sommets est hamiltonien alors que d(u) + d(v) = 4 < 5.', 'Parce que le graphe est forcément complet.', 'Parce que le théorème ne s’applique qu’aux graphes orientés.', 'Parce que d(u) + d(v) ne peut pas être inférieur à n.'], 0, '<p>Le théorème de la diapo 27 dit « si la condition est remplie alors G est hamiltonien », pas l’inverse. Contre-exemple : le cycle à 5 sommets (d(u) + d(v) = 4 < 5) est hamiltonien.</p>', { graph: C5, src: 'extra', tag: 'hamilton-conditions', hints: ['Une implication ne se renverse pas : cherchez un graphe hamiltonien qui ne vérifie pas la condition.'] }),
      qb.choice('n14.q11', 3, 'Un livreur doit passer une seule fois chez chacun de six clients puis revenir à son dépôt (sommets = clients et dépôt, arêtes = routes directes). Cette tournée correspond à…', ['un cycle hamiltonien', 'un cycle eulérien', 'une chaîne eulérienne', 'une composante connexe'], 0, '<p>On doit visiter chaque <b>sommet</b> (client, dépôt) une seule fois et revenir au point de départ : c’est un cycle hamiltonien. (Un cycle eulérien correspondrait à parcourir chaque <i>route</i> une seule fois.)</p>', { transfer: true, tag: 'hamilton-conditions', hints: ['Modélisez : visiter chaque client = visiter chaque sommet.'] }),
      qb.edges('n14.q12', 3, 'Écrivez la liste des arêtes d’un graphe simple non orienté sur les six sommets A, B, C, D, E, F qui est <b>hamiltonien</b> mais dont <b>aucun sommet n’a un degré supérieur ou égal à n/2 = 3</b> (il ne satisfait donc pas le corollaire de la diapo 27).', function (g) {
        var vs = ['A', 'B', 'C', 'D', 'E', 'F'];
        if (!hasAll(g, vs)) return { ok: false, msg: 'Le graphe doit avoir exactement les six sommets A à F.' };
        if (!GR.isSimple(g)) return { ok: false, msg: 'Le graphe doit être simple (ni boucle, ni arête répétée).' };
        var md = GR.maxDegree(g);
        if (md >= 3) return { ok: false, msg: 'Un de vos sommets a un degré ' + md + ' ≥ 3 ; tous les degrés doivent rester inférieurs ou égaux à 2.' };
        var h = GR.hamilton(g);
        if (!h.cycle) return { ok: false, msg: 'Votre graphe n’a pas de cycle hamiltonien.' };
        return { ok: true };
      }, '<p>Le cycle à 6 sommets A–B–C–D–E–F–A : chaque sommet est de degré 2 < 3 et le cycle lui-même est un cycle hamiltonien. C’est une illustration du fait que les conditions de la diapo 27 sont suffisantes mais pas nécessaires.</p>', { sample: 'A-B, B-C, C-D, D-E, E-F, F-A', challenge: true, tag: 'hamilton-conditions', hints: ['Tous les degrés doivent valoir au plus 2.', 'Un graphe de degrés ≤ 2 qui a un cycle passant par tous les sommets est un cycle.'] })
    ]
  });
  })();
  /*SUITE*/
})(typeof self !== 'undefined' ? self : (typeof global !== 'undefined' ? global : this));
